    if (found && found.name) {
      const m = found.name.match(/^(.*?)\s*\(\s*(.*?)\s*\/\s*(.*?)\s*\)$/);
      if (m) {
        if (lang === 'te') return m[2].trim();
        if (lang === 'hi') return m[3].trim();
        if (lang === 'en') return m[1].trim();
      }
      return found.name.split(' (')[0];
    }
