function TL(en, te, hi, ta, kn, ml, mr, bn, gu, pa, or) {
  if (currentLang === 'te') return te || en;
  if (currentLang === 'hi') return hi || en;
  if (currentLang === 'en') return en;

  if (currentLang === 'ta' && ta) return ta;
  if (currentLang === 'kn' && kn) return kn;
  if (currentLang === 'ml' && ml) return ml;
  if (currentLang === 'mr' && mr) return mr;
  if (currentLang === 'bn' && bn) return bn;
  if (currentLang === 'gu' && gu) return gu;
  if (currentLang === 'pa' && pa) return pa;
  if (currentLang === 'or' && or) return or;

  const dict = MASTER_PAN_INDIAN_TRANSLATIONS[currentLang];
  if (dict) {
    if (dict[en]) return dict[en];
    if (dict[te]) return dict[te];
    if (dict[hi]) return dict[hi];
  }

  if (typeof PAN_INDIAN_PHRASE_MAP !== 'undefined' && PAN_INDIAN_PHRASE_MAP[en]?.[currentLang]) {
    return PAN_INDIAN_PHRASE_MAP[en][currentLang];
  }

  return hi || te || en;
}

function locObj(obj, field = '') {
  if (!obj) return '';
  if (typeof obj === 'string') return TL(obj, obj, obj);
  if (field && obj[field]) {
    return locObj(obj[field]);
  }
  if (obj[currentLang]) return obj[currentLang];

  if (obj.en) {
    const translated = TL(obj.en, obj.te, obj.hi);
    if (translated && translated !== obj.en) return translated;
  }

  if (currentLang === 'te' && obj.te) return obj.te;
  if (currentLang === 'hi' && obj.hi) return obj.hi;

  return obj.en || obj.te || obj.hi || Object.values(obj)[0] || '';
}


