let selectedTruckToBook = null;
let bookingTruckBags = 10;

function openTruckBookingModal(truckId) {
  const truck = MANDI_TRUCKS_CATALOG.find(t => t.id === truckId) || MANDI_TRUCKS_CATALOG[0];
  selectedTruckToBook = truck;
  bookingTruckBags = 10;

  const modal = document.getElementById('truck-booking-modal');
  const title = document.getElementById('tb-title');
  const sub = document.getElementById('tb-sub');
  
  const isTe = currentLang === 'te';
  const isHi = currentLang === 'hi';

  if (title) title.textContent = `${truck.vehicle[currentLang] || truck.vehicle.en} · ${truck.driver[currentLang] || truck.driver.en}`;
  if (sub) sub.textContent = `${truck.dest[currentLang] || truck.dest.en} · ${truck.leavesAt[currentLang] || truck.leavesAt.en}`;

  updateTruckBookingModalDom();
  if (modal) modal.style.display = 'flex';
}

function closeTruckBookingModal(e) {
  const modal = document.getElementById('truck-booking-modal');
  if (modal) modal.style.display = 'none';
}

function adjustTruckBags(delta) {
  bookingTruckBags = Math.max(1, Math.min(50, bookingTruckBags + delta));
  updateTruckBookingModalDom();
}

function updateTruckBookingModalDom() {
  const body = document.getElementById('tb-content-body');
  if (!body || !selectedTruckToBook) return;

  const t = selectedTruckToBook;
  const isTe = currentLang === 'te';
  const isHi = currentLang === 'hi';

  const quintals = (bookingTruckBags * 0.5); // 50kg bag = 0.5 Qtl
  const sharedCost = Math.round(quintals * t.ratePerQtl);
  const soloMarketRate = Math.round(sharedCost * 2.8);
  const savings = soloMarketRate - sharedCost;

  body.innerHTML = `
    <!-- Route & Driver Info Card -->
    <div class="m3-card" style="padding:14px;background:#FFF7ED;border:1px solid #FFEDD5;margin-bottom:12px;">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">
        <span style="font-size:12px;font-weight:900;color:#C2410C;">📍 ${TL('Destination', 'మార్కెట్ గమ్యం', 'Destination')}: ${t.dest[currentLang]||t.dest.en}</span>
        <span style="font-size:11px;font-weight:800;color:#15803D;background:#DCFCE7;padding:2px 8px;border-radius:6px;">${t.rating}</span>
      </div>
      <div style="font-size:11px;color:#475569;">👨‍✈️ ${TL('Driver', 'డ్రైవర్', 'Driver')}: <strong>${t.driver[currentLang]||t.driver.en}</strong> · 📞 ${t.phone}</div>
      <div style="font-size:11px;color:#EA580C;font-weight:800;margin-top:4px;">⏱️ ${t.leavesAt[currentLang]||t.leavesAt.en}</div>
    </div>

    <!-- Bag / Weight Selector -->
    <div class="m3-card" style="padding:14px;margin-bottom:12px;">
      <div style="font-size:11px;font-weight:800;color:#64748B;margin-bottom:6px;">${TL('Number of Crop Bags (50kg Bag)', 'మీ పంట బస్తాల సంఖ్య (50 కేజీల బస్తా)', 'Number of Crop Bags (50kg Bag)')}:</div>
      <div style="display:flex;align-items:center;justify-content:space-between;background:#F1F5F9;padding:8px 14px;border-radius:12px;">
        <div>
          <span style="font-size:15px;font-weight:900;color:#0F172A;">${bookingTruckBags} ${TL('Bags', 'బస్తాలు', 'Bags')}</span>
          <span style="font-size:11px;color:#64748B;margin-left:6px;">(${quintals} ${TL('Quintals', 'క్వింటాళ్లు', 'Quintals')})</span>
        </div>
        <div style="display:flex;gap:8px;">
          <button onclick="adjustTruckBags(-2)" style="width:32px;height:32px;background:#FFFFFF;border:1px solid #CBD5E1;border-radius:8px;font-weight:900;font-size:16px;cursor:pointer;">-</button>
          <button onclick="adjustTruckBags(2)" style="width:32px;height:32px;background:#EA580C;color:#FFFFFF;border:none;border-radius:8px;font-weight:900;font-size:16px;cursor:pointer;">+</button>
        </div>
      </div>
    </div>

    <!-- Fare & Savings Breakdown -->
    <div class="m3-card" style="padding:14px;background:#E8F5E9;margin-bottom:14px;">
      <div style="display:flex;justify-content:space-between;font-size:11px;padding:3px 0;">
        <span>${TL('Solo Private Truck Cost:', 'వ్యక్తిగత ప్రైవేట్ లారీ చార్జీ:', 'Solo Private Truck Cost:')}</span>
        <span style="text-decoration:line-through;color:#94A3B8;">₹${soloMarketRate.toLocaleString()}</span>
      </div>
      <div style="display:flex;justify-content:space-between;font-size:11px;padding:3px 0;">
        <span>${TL('Pooled Freight Rate:', 'ఉమ్మడి రవాణా రేటు:', 'Pooled Freight Rate:')}</span>
        <span>₹${t.ratePerQtl}/Qtl × ${quintals} Qtl</span>
      </div>
      <div style="display:flex;justify-content:space-between;font-size:14px;font-weight:900;color:#1B5E20;border-top:1px solid #C8E6C9;padding-top:6px;margin-top:4px;">
        <span>${TL('Your Pooled Fare:', 'మీరు చెల్లించవలసిన మొత్తం:', 'Your Pooled Fare:')}</span>
        <span>₹${sharedCost.toLocaleString()}</span>
      </div>
      <div style="font-size:10px;font-weight:800;color:#15803D;background:#DCFCE7;padding:3px 8px;border-radius:6px;margin-top:6px;text-align:center;">
        🎉 ${TL(`You save ₹${savings.toLocaleString()} (64%) with GramHaul pooling!`, `ఉమ్మడి రవాణా వల్ల మీరు ₹${savings.toLocaleString()} ఆదా చేసుకుంటున్నారు!`, `You save ₹${savings.toLocaleString()} (64%) with GramHaul pooling!`)}
      </div>
    </div>

    <button class="action-btn-green" onclick="submitTruckBooking()" style="background:#EA580C;">
      🚚 ${TL(`Confirm Shared Freight Slot (₹${sharedCost.toLocaleString()})`, `స్లాట్ కన్ఫర్మ్ చేయండి (₹${sharedCost.toLocaleString()})`, `Confirm Shared Freight Slot (₹${sharedCost.toLocaleString()})`)}
    </button>
  `;
}

function submitTruckBooking() {
  const t = selectedTruckToBook;
  if (!t) return;
  const isTe = currentLang === 'te';
  const isHi = currentLang === 'hi';
  const bookId = 'GH-TRUCK-' + Math.floor(100000 + Math.random() * 900000);

  closeTruckBookingModal(null);
  alert(TL(`✅ Shared Freight Slot Booked Successfully!\nBooking ID: ${bookId}\nDriver (${t.driver.en}): 📞 ${t.phone}\nScheduled arrival: ${t.leavesAt.en}.`, `✅ ఉమ్మడి రవాణా స్లాట్ విజయవంతంగా బుక్ అయింది!\nబుకింగ్ ID: ${bookId}\nడ్రైవర్ (${t.driver.te}): 📞 ${t.phone}\n${t.leavesAt.te} మీ గ్రామానికి చేరుకుంటారు.`, `✅ शेयर्ड ट्रक स्लॉट सफलतापूर्वक बुक हुआ!\nबुकिंग आईडी: ${bookId}\nचालक (${t.driver.hi}): 📞 ${t.phone}\n${t.leavesAt.hi} आपके गांव पहुंचेंगे।`));
}

