function getFilteredMandiRates() {
  const cropQ = (mandiSearchCrop || '').toLowerCase().trim();
  const stateQ = (mandiSearchState || '').toLowerCase().trim();
  const mandiQ = (mandiSearchMandi || '').toLowerCase().trim();

  // Strict primary match
  const exactMatches = AGMARKNET_MANDI_CATALOG.filter(item => {
    if (mandiSelectedPopular !== 'all' && item.cropKey !== mandiSelectedPopular) {
      return false;
    }
    if (cropQ) {
      const matchName = (item.cropName.en + ' ' + item.cropName.te + ' ' + item.cropName.hi + ' ' + item.cropKey + ' ' + item.variety.en + ' ' + item.variety.te).toLowerCase();
      if (!matchName.includes(cropQ)) return false;
    }
    if (stateQ) {
      const matchState = (item.state.en + ' ' + item.state.te + ' ' + item.state.hi).toLowerCase();
      if (!matchState.includes(stateQ)) return false;
    }
    if (mandiQ) {
      const matchMandi = (item.mandi.en + ' ' + item.mandi.te + ' ' + item.mandi.hi + ' ' + item.district).toLowerCase();
      if (!matchMandi.includes(mandiQ)) return false;
    }
    return true;
  });

  if (exactMatches.length > 0) {
    return exactMatches;
  }

  // Fallback 1: If crop matches, show all mandis for that crop
  if (cropQ || mandiSelectedPopular !== 'all') {
    const targetCrop = (mandiSelectedPopular !== 'all' ? mandiSelectedPopular : cropQ).toLowerCase();
    const cropFallbacks = AGMARKNET_MANDI_CATALOG.filter(item => {
      const matchName = (item.cropName.en + ' ' + item.cropName.te + ' ' + item.cropName.hi + ' ' + item.cropKey + ' ' + item.cropSlug).toLowerCase();
      return matchName.includes(targetCrop);
    });
    if (cropFallbacks.length > 0) return cropFallbacks;

    // Dynamic generation for any of the 120+ crops from OpenFarm catalog
    const foundIn120 = OPENFARM_CROPS_CATALOG.find(c => c.id.toLowerCase() === targetCrop || getLocalizedCropName(c.id).toLowerCase().includes(targetCrop) || (CROP_TRANSLATIONS[c.id]?.en || '').toLowerCase().includes(targetCrop));
    if (foundIn120) {
      const dynSlug = foundIn120.id;
      const dynNameEn = CROP_TRANSLATIONS[dynSlug]?.en || dynSlug;
      const dynNameTe = CROP_TRANSLATIONS[dynSlug]?.te || dynNameEn;
      const dynNameHi = CROP_TRANSLATIONS[dynSlug]?.hi || dynNameEn;
      const dynBasePrice = parseInt((foundIn120.price || '₹2,400').replace(/[^0-9]/g, '')) || 2400;
      return [
        {
          id: 'dyn-mkt-' + dynSlug + '-0',
          cropKey: dynSlug,
          cropSlug: dynSlug,
          cropPath: `${dynSlug}/${dynSlug}.svg`,
          cropName: { en: dynNameEn + ' (A-Grade)', te: dynNameTe + ' (A-గ్రేడ్)', hi: dynNameHi + ' (ग्रेड A)' },
          variety: { en: 'Desi Pure / Standard FAQ', te: 'ప్రామాణిక దేశీ రకం', hi: 'मानक देसी किस्म' },
          mandi: { en: 'Warangal APMC Yard', te: 'వరంగల్ ఏనుమాముల మార్కెట్ యార్డ్', hi: 'वारंगल मंडी' },
          district: 'Warangal',
          state: { en: 'Telangana', te: 'తెలంగాణ', hi: 'तेलंगाना' },
          modalPrice: dynBasePrice,
          minPrice: Math.round(dynBasePrice * 0.85),
          maxPrice: Math.round(dynBasePrice * 1.15),
          mspPrice: Math.round(dynBasePrice * 0.95),
          unit: foundIn120.unit || '/Qtl',
          arrivals: 3200,
          change: '+5.4%',
          up: true,
          badge: '📍 Local Mandi'
        },
        {
          id: 'dyn-mkt-' + dynSlug + '-1',
          cropKey: dynSlug,
          cropSlug: dynSlug,
          cropPath: `${dynSlug}/${dynSlug}.svg`,
          cropName: { en: dynNameEn + ' (Export Quality)', te: dynNameTe + ' (ప్రీమియం నాణ్యత)', hi: dynNameHi + ' (प्रीमियम)' },
          variety: { en: 'Premium Selection', te: 'ప్రీమియం సెలక్షన్', hi: 'प्रीमियम चयन' },
          mandi: { en: 'Bowenpally APMC, Hyderabad', te: 'బోయిన్‌పల్లి మార్కెట్, హైదరాబాద్', hi: 'बोवेनपल्ली मंडी' },
          district: 'Hyderabad',
          state: { en: 'Telangana', te: 'తెలంగాణ', hi: 'तेलंगाना' },
          modalPrice: Math.round(dynBasePrice * 1.08),
          minPrice: Math.round(dynBasePrice * 0.9),
          maxPrice: Math.round(dynBasePrice * 1.25),
          mspPrice: Math.round(dynBasePrice * 0.95),
          unit: foundIn120.unit || '/Qtl',
          arrivals: 5100,
          change: '+7.2%',
          up: true,
          badge: '⚡ High Demand'
        }
      ];
    }
  }

  // Fallback 2: If state matches, show mandis in that state
  if (stateQ) {
    const stateFallbacks = AGMARKNET_MANDI_CATALOG.filter(item => {
      const matchState = (item.state.en + ' ' + item.state.te + ' ' + item.state.hi).toLowerCase();
      return matchState.includes(stateQ);
    });
    if (stateFallbacks.length > 0) return stateFallbacks;
  }

  return AGMARKNET_MANDI_CATALOG;
}

