function executeMandiSearch() {
  const cropEl = document.getElementById('mandi-crop-inp');
  const stateEl = document.getElementById('mandi-state-inp');
  const mktEl = document.getElementById('mandi-mkt-inp');

  if (cropEl) mandiSearchCrop = cropEl.value;
  if (stateEl) mandiSearchState = stateEl.value;
  if (mktEl) mandiSearchMandi = mktEl.value;

  const container = document.getElementById('mandi-results-container');
  if (container) {
    container.innerHTML = renderMandiCardsHtml();
  }
}

function autoDetectMandiLocation() {
  const stateEl = document.getElementById('mandi-state-inp');
  const mktEl = document.getElementById('mandi-mkt-inp');
  const detected = liveWeather.locationName.en || 'Warangal, Telangana';
  const parts = detected.split(',').map(s=>s.trim());
  const city = parts[0] || 'Warangal';
  const st = parts[1] || 'Telangana';

  if (stateEl) stateEl.value = st;
  if (mktEl) mktEl.value = city;

  mandiSearchState = st;
  mandiSearchMandi = city;
  mandiSelectedPopular = 'all';

  executeMandiSearch();
  alert(currentLang==='te'?`📍 స్థానం గుర్తించబడింది: ${city}, ${st}`:(currentLang==='hi'?`📍 लोकेशन खोजी गई: ${city}, ${st}`:`📍 Location Auto-Detected: ${city}, ${st}`));
}


function formatHourAmPm(h) {
  const hNorm = (h % 24 + 24) % 24;
  const ampm = hNorm >= 12 ? 'PM' : 'AM';
  const h12 = hNorm % 12 === 0 ? 12 : hNorm % 12;
  return (h12 < 10 ? '0' : '') + h12 + ':00 ' + ampm;
}

function triggerSprayAlarm(timeRange) {
  if (currentLang === 'te') {
    alert('✅ స్ప్రేయింగ్ అలారం రిమైండర్ సెట్ చేయబడింది: ' + timeRange + '!');
  } else if (currentLang === 'hi') {
    alert('✅ छिड़काव अलार्म सेट किया गया: ' + timeRange + '!');
  } else {
    alert('✅ Spray reminder alarm set successfully for ' + timeRange + '!');
  }
}

function getDynamicSprayWindows() {
  const now = new Date();
  const curHour = now.getHours();

  const windows = [];

  for (let i = 0; i < 4; i++) {
    const startH = (curHour + (i * 3)) % 24;
    const endH = (startH + 3) % 24;
    const isNow = i === 0;

    let status = 'optimal';
    let badgeText = {
      en: '🟢 Optimal Window', te: '🟢 ఉత్తమ సమయం', hi: '🟢 आदर्श समय',
      ta: '🟢 சிறந்த நேரம்', kn: '🟢 ಸೂಕ್ತ ಸಮಯ', ml: '🟢 ഏറ്റവും നല്ലത്',
      mr: '🟢 उत्तम वेळ', bn: '🟢 উপযুক্ত সময়', gu: '🟢 શ્રેષ્ઠ સમય',
      pa: '🟢 ਉੱਤਮ ਸਮਾਂ', or: '🟢 ଉତ୍ତମ ସମୟ'
    };
    let tagBg = '#DCFCE7';
    let tagColor = '#15803D';
    let desc = {
      en: 'Cool canopy & low wind. Highest leaf absorption efficiency.',
      te: 'తక్కువ గాలి & చల్లని వాతావరణం. మందు సమర్థవంతంగా పనిచేస్తుంది.',
      hi: 'ठंडा मौसम व शांत हवा। दवा पत्तियों पर तेजी से असर करेगी।'
    };
    let estWind = Math.min(Math.max(parseInt(liveWeather.wind || 9) + (i % 2 === 0 ? -1 : 2), 6), 14);
    let estTemp = 26;

    if (startH >= 11 && startH < 15) {
      status = 'avoid';
      badgeText = {
        en: '🔴 Avoid Spraying', te: '🔴 వాయిదా వేయండి', hi: '🔴 छिड़काव न करें',
        ta: '🔴 தவிர்க்கவும்', kn: '🔴 ತಪ್ಪಿಸಿ', ml: '🔴 ഒഴിവാക്കുക',
        mr: '🔴 टाळा', bn: '🔴 এড়িয়ে চলুন', gu: '🔴 ટાળો',
        pa: '🔴 ਬਚੋ', or: '🔴 ବନ୍ଦ ରଖନ୍ତୁ'
      };
      tagBg = '#FEE2E2';
      tagColor = '#DC2626';
      desc = {
        en: 'Intense solar heat & thermal updrafts cause chemical vaporization.',
        te: 'తీవ్ర ఎండ & ఉష్ణోగ్రత వల్ల మందు ఆవిరైపోతుంది.',
        hi: 'तेज़ धूप के कारण दवा जल्दी वाष्पीकृत हो जाती है।'
      };
      estTemp = 32;
      estWind = 13;
    } else if (startH >= 15 && startH < 18) {
      status = 'caution';
      badgeText = {
        en: '🟡 Moderate Window', te: '🟡 సాధారణ సమయం', hi: '🟡 मध्यम समय',
        ta: '🟡 மிதமான நேரம்', kn: '🟡 ಸಾಧಾರಣ ಸಮಯ', ml: '🟡 ഇടത്തരം',
        mr: '🟡 मध्यम वेळ', bn: '🟡 মাঝারি সময়', gu: '🟡 મધ્યમ સમય',
        pa: '🟡 ਦਰਮਿਆਨਾ ਸਮਾਂ', or: '🟡 ସାଧାରଣ ସମୟ'
      };
      tagBg = '#FEF3C7';
      tagColor = '#D97706';
      desc = {
        en: 'Sun declining. Check field wind drift before tank mix.',
        te: 'ఎండ తగ్గుముఖం పట్టింది. గాలి వేగాన్ని గమనించి స్ప్రే చేయండి.',
        hi: 'धूप कम हो रही है। हवा की दिशा देखकर छिड़काव करें।'
      };
      estTemp = 29;
      estWind = 11;
    } else if (startH >= 18 || startH < 6) {
      status = 'safe';
      badgeText = {
        en: isNow ? '🟢 Safe (Active Now)' : '🟢 Safe Window',
        te: isNow ? '🟢 ఇప్పుడు అనుకూలం' : '🟢 అనుకూల సమయం',
        hi: isNow ? '🟢 अभी सुरक्षित है' : '🟢 सुरक्षित समय',
        ta: isNow ? '🟢 இப்போது பாதுகாப்பானது' : '🟢 பாதுகாப்பான நேரம்',
        kn: isNow ? '🟢 ಈಗ ಸುರಕ್ಷಿತ' : '🟢 ಸುರಕ್ಷಿತ ಸಮಯ',
        ml: isNow ? '🟢 ഇപ്പോൾ സുരക്ഷിതം' : '🟢 സുരക്ഷിത സമയം',
        mr: isNow ? '🟢 आता सुरक्षित' : '🟢 सुरक्षित वेळ',
        bn: isNow ? '🟢 এখন নিরাপদ' : '🟢 নিরাপদ সময়',
        gu: isNow ? '🟢 અત્યારે સુરક્ષિત' : '🟢 સુરક્ષિત સમય',
        pa: isNow ? '🟢 ਹੁਣ ਸੁਰੱਖਿਅਤ ਹੈ' : '🟢 ਸੁਰੱਖਿਅਤ ਸਮਾਂ',
        or: isNow ? '🟢 ବର୍ତ୍ତମାନ ସୁରକ୍ଷିତ' : '🟢 ସୁରକ୍ଷିତ ସମୟ'
      };
      tagBg = '#DCFCE7';
      tagColor = '#15803D';
      desc = {
        en: 'Calm night breeze & high humidity. Stomata absorb with zero drift.',
        te: 'ప్రశాంతమైన రాత్రి గాలి & తేమ. మందు గాలికి ఎగిరిపోకుండా మొక్కలపై నిలుస్తుంది.',
        hi: 'शांत हवा व पर्याप्त नमी। दवा पत्तियों पर जमकर असर करेगी।'
      };
      estTemp = 24;
      estWind = 7;
    }

    windows.push({
      timeRange: formatHourAmPm(startH) + ' - ' + formatHourAmPm(endH),
      isNow,
      status,
      badgeText: badgeText[currentLang] || badgeText.en,
      tagBg,
      tagColor,
      desc: desc[currentLang] || desc.en,
      estWind,
      estTemp
    });
  }

  return windows;
}

