function openPriceAlertModal(itemId, initialTab) {
  notificationTab = initialTab || (itemId ? 'manage' : 'feed');
  const item = itemId ? (AGMARKNET_MANDI_CATALOG.find(x => x.id === itemId) || getFilteredMandiRates().find(x => x.id === itemId) || selectedPriceTrendItem || AGMARKNET_MANDI_CATALOG[0]) : (selectedPriceTrendItem || AGMARKNET_MANDI_CATALOG[0]);
  currentAlertItem = item;
  currentAlertTargetPrice = Math.round(item.modalPrice * 1.08 / 10) * 10;

  const modal = document.getElementById('price-alert-modal');
  const title = document.getElementById('pa-modal-title');
  const sub = document.getElementById('pa-modal-sub');

  const isTe = currentLang === 'te';
  const isHi = currentLang === 'hi';

  if (title) title.textContent = TL('Notifications & Alerts Center', 'నోటిఫికేషన్లు & హెచ్చరికలు', 'सूचनाएं व अलर्ट केंद्र');
  if (sub) sub.textContent = TL('Real-Time App Notifications & Subsystem Alerts', 'నిజ-సమయ వ్యవసాయ సందేశాలు & మార్కెట్ హెచ్చరికలు', 'वास्तविक कृषि अलर्ट व आवश्यक सूचनाएं');

  renderPriceAlertModalDom();
  if (modal) modal.style.display = 'flex';
}

function setNotificationTab(tab) {
  notificationTab = tab;
  renderPriceAlertModalDom();
}

function setNotifFilter(cat) {
  notifFilterCategory = cat;
  renderPriceAlertModalDom();
}

function markAllNotificationsRead() {
  APP_NOTIFICATIONS.forEach(n => n.read = true);
  // Hide all badge indicators everywhere
  ['home-notif-dot','modal-unread-count-badge','notif-bell-badge'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.style.display = 'none';
  });
  // Re-render the notification list in the currently open modal only
  renderPriceAlertModalDom();
}

function handleNotifAction(screenKey) {
  closePriceAlertModal();
  closePriceTrendModal();
  openScreen(screenKey || 'home');
  syncSideNav('btn-' + (screenKey || 'home'));
}
