function openPriceAlertModal(itemId) {
  const item = AGMARKNET_MANDI_CATALOG.find(x => x.id === itemId) || getFilteredMandiRates().find(x => x.id === itemId) || selectedPriceTrendItem || AGMARKNET_MANDI_CATALOG[0];
  currentAlertItem = item;
  currentAlertTargetPrice = Math.round(item.modalPrice * 1.08 / 10) * 10;

  const modal = document.getElementById('price-alert-modal');
  const title = document.getElementById('pa-modal-title');
  const sub = document.getElementById('pa-modal-sub');

  const isTe = currentLang === 'te';
  const isHi = currentLang === 'hi';

  if (title) title.textContent = `${item.cropName[currentLang]||item.cropName.en} - ${TL('Set Price Alert', 'ధర అలర్ట్', 'Set Price Alert')}`;
  if (sub) sub.textContent = TL('Real-Time SMS & Push Notification Triggers', 'నిజ సమయ SMS & పుష్ నోటిఫికేషన్ హెచ్చరికలు', 'रीयल-टाइम एसएमएस व मोबाइल पुश नोटिफिकेशन');

  renderPriceAlertModalDom();
  if (modal) modal.style.display = 'flex';
}

function closePriceAlertModal(e) {
  const modal = document.getElementById('price-alert-modal');
  if (modal) modal.style.display = 'none';
}

function adjustAlertTargetPrice(delta) {
  if (!currentAlertItem) return;
  currentAlertTargetPrice = Math.max(currentAlertItem.modalPrice + 10, currentAlertTargetPrice + delta);
  renderPriceAlertModalDom();
}

function setAlertPercentageGain(percent) {
  if (!currentAlertItem) return;
  currentAlertTargetPrice = Math.round((currentAlertItem.modalPrice * (1 + percent / 100)) / 10) * 10;
  renderPriceAlertModalDom();
}

function setAlertMspTarget() {
  if (!currentAlertItem) return;
  currentAlertTargetPrice = currentAlertItem.mspPrice || Math.round(currentAlertItem.modalPrice * 1.05);
  renderPriceAlertModalDom();
}

function toggleAlertChannel(channel) {
  if (channel === 'sms') currentAlertChannelSms = !currentAlertChannelSms;
  if (channel === 'push') currentAlertChannelPush = !currentAlertChannelPush;
  renderPriceAlertModalDom();
}

function saveCurrentPriceAlert() {
  const item = currentAlertItem;
  if (!item) return;

  const phoneInp = document.getElementById('pa-phone-inp');
  if (phoneInp) currentAlertPhone = phoneInp.value.trim() || '9849022338';

  const isTe = currentLang === 'te';
  const isHi = currentLang === 'hi';

  const newAlert = {
    id: 'pa-' + Date.now(),
    cropKey: item.cropKey || item.cropSlug,
    cropSlug: item.cropSlug,
    cropName: item.cropName,
    mandi: item.mandi,
    state: item.state,
    basePrice: item.modalPrice,
    targetPrice: currentAlertTargetPrice,
    unit: item.unit || '/Qtl',
    phone: currentAlertPhone,
    channelSms: currentAlertChannelSms,
    channelPush: currentAlertChannelPush,
    active: true,
    createdDate: TL('Today', 'ఈరోజు', 'आज')
  };

  const existingIdx = activePriceAlerts.findIndex(a => a.cropSlug === item.cropSlug && a.mandi.en === item.mandi.en);
  if (existingIdx !== -1) {
    activePriceAlerts[existingIdx] = newAlert;
  } else {
    activePriceAlerts.unshift(newAlert);
  }

  closePriceAlertModal();

  showPushNotificationToast({
    title: TL(`🔔 Price Alert Activated!`, `🔔 ధర అలర్ట్ సక్రియం చేయబడింది!`, `🔔 भाव अलर्ट सक्रिय हो गया!`),
    msg: TL(`You will receive instant SMS & Push alerts on ${currentAlertPhone} when ${item.cropName.en} hits ₹${currentAlertTargetPrice.toLocaleString()}${item.unit}.`, `${item.cropName.te} ధర ₹${currentAlertTargetPrice.toLocaleString()}${item.unit} చేరినప్పుడు మీ మొబైల్ (${currentAlertPhone}) కు తక్షణ SMS/నోటిఫికేషన్ వస్తుంది.`, `${item.cropName.hi} का भाव ₹${currentAlertTargetPrice.toLocaleString()}${item.unit} पहुंचने पर मोबाइल (${currentAlertPhone}) पर एसएमएस मिलेगा।`),
    type: 'prescription_saved',
    cropSlug: item.cropSlug,
    mandiEn: item.mandi.en
  });
}

function togglePriceAlertActive(alertId) {
  const alert = activePriceAlerts.find(a => a.id === alertId);
  if (alert) {
    alert.active = !alert.active;
    renderPriceAlertModalDom();
  }
}

function deletePriceAlert(alertId) {
  activePriceAlerts = activePriceAlerts.filter(a => a.id !== alertId);
  renderPriceAlertModalDom();
}

function triggerPriceSurgeNotification(alert, surgePrice) {
  if (!alert) return;
  const isTe = currentLang === 'te';
  const isHi = currentLang === 'hi';
  const actualSurge = surgePrice || (alert.targetPrice + 40);

  showPushNotificationToast({
    title: TL(`📈 MANDI SURGE ALERT: Target Rate Hit!`, `📈 ధర పెరుగుదల అలర్ట్: లక్ష్య ధరను దాటింది!`, `📈 भाव वृद्धि अलर्ट: लक्ष्य पार हो गया!`),
    msg: TL(`🔥 ${typeof alert.cropName==='object'?(alert.cropName.en):alert.cropName} at ${typeof alert.mandi==='object'?(alert.mandi.en):alert.mandi} surged to ₹${actualSurge.toLocaleString()}/Qtl! (Target ₹${alert.targetPrice.toLocaleString()} reached). Book freight now to lock maximum profit!`, `🔥 ${typeof alert.cropName==='object'?(alert.cropName.te||alert.cropName.en):alert.cropName} (${typeof alert.mandi==='object'?(alert.mandi.te||alert.mandi.en):alert.mandi}) లో ధర పెరిగి ₹${actualSurge.toLocaleString()}/Qtl కు చేరింది! (లక్ష్యం: ₹${alert.targetPrice.toLocaleString()}). రవాణా బుక్ చేసి విక్రయించండి!`, `🔥 ${typeof alert.cropName==='object'?(alert.cropName.hi||alert.cropName.en):alert.cropName} (${typeof alert.mandi==='object'?(alert.mandi.hi||alert.mandi.en):alert.mandi}) में भाव बढ़कर ₹${actualSurge.toLocaleString()}/Qtl हुआ! (लक्ष्य: ₹${alert.targetPrice.toLocaleString()})। तुरंत ट्रक बुक करें!`),
    type: 'price_surge',
    cropSlug: alert.cropSlug,
    mandiEn: typeof alert.mandi==='object'?alert.mandi.en:alert.mandi
  });

  try {
    const ctx = new (window.AudioContext || window.webkitAudioContext)();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.frequency.setValueAtTime(587.33, ctx.currentTime);
    osc.frequency.setValueAtTime(880, ctx.currentTime + 0.12);
    gain.gain.setValueAtTime(0.3, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.45);
    osc.start();
    osc.stop(ctx.currentTime + 0.5);
  } catch (e) {}
}

function checkAndTriggerRealtimeAlerts() {
  if (!activePriceAlerts || activePriceAlerts.length === 0) return;
  activePriceAlerts.forEach(alert => {
    if (!alert.active) return;
    // Check against live rates in AGMARKNET_MANDI_CATALOG or dynamic defaults
    const info = getMandiDefaults(alert.cropSlug || alert.cropKey);
    const liveRate = info.rawPrice || parseInt((info.price||'0').replace(/[^0-9]/g,'')) || alert.basePrice;
    if (liveRate >= alert.targetPrice) {
      triggerPriceSurgeNotification(alert, liveRate);
    }
  });
}

function simulatePriceAlertTrigger(alertId) {
  const alert = activePriceAlerts.find(a => a.id === alertId) || activePriceAlerts[0];
  if (!alert) return;
  closePriceAlertModal();
  closePriceTrendModal();
  triggerPriceSurgeNotification(alert, alert.targetPrice + 40);
}


function showPushNotificationToast(payload) {
  // Suppress in-app toasts during splash/onboarding experience
  const startupOverlay = document.getElementById('startup-experience-overlay');
  if (startupOverlay && startupOverlay.style.display !== 'none' && !localStorage.getItem('nukrop_onboarding_completed')) {
    return;
  }
  lastToastPayload = payload;
  const sysTitle = (payload && payload.title) || 'NuKropAI Notification';
  const sysMsg = (payload && payload.msg) || '';

  // 1. Post Real Native Android OS Notification in phone status bar / lock screen
  if (window.AndroidBridge && typeof window.AndroidBridge.postSystemNotification === 'function') {
    try {
      window.AndroidBridge.postSystemNotification(sysTitle, sysMsg);
    } catch(e) {
      console.warn('postSystemNotification failed:', e);
    }
    // STRICT USER REQUIREMENT: In mobile app, NEVER display HTML in-app messages! Only real Android notifications!
    return;
  }
  
  // Real Android System Notification (appears in phone status bar & lock screen like a message)
  try {
    if (window.AndroidBridge && typeof window.AndroidBridge.postSystemNotification === 'function') {
      const sysTitle = (payload && payload.title) || 'NuKropAI Notification';
      const sysMsg = (payload && payload.msg) || '';
      window.AndroidBridge.postSystemNotification(sysTitle, sysMsg);
    }
  } catch(errSys) {
    console.warn('Native notification bridge error:', errSys);
  }
  const toast = document.getElementById('global-push-toast');
  const titleEl = document.getElementById('toast-title');
  const msgEl = document.getElementById('toast-msg');
  const appNameEl = document.getElementById('toast-app-name');
  const timeEl = document.getElementById('toast-time');
  const iconEl = document.getElementById('toast-icon');
  const actionBtn = document.getElementById('toast-action-btn');

  if (!toast) return;

  const isTe = currentLang === 'te';
  const isHi = currentLang === 'hi';

  if (titleEl) titleEl.textContent = payload.title;
  if (msgEl) msgEl.textContent = payload.msg;
  if (timeEl) timeEl.textContent = TL('Just now', 'ఇప్పుడే', 'अभी');

  if (payload.type === 'prescription_saved') {
    if (appNameEl) appNameEl.textContent = TL('📄 DIGITAL HEALTH PASSPORT', '📄 డిజిటల్ హెల్త్ పాస్‌పోర్ట్', '📄 डिजिटल हेल्थ पासपोर्ट');
    if (iconEl) iconEl.textContent = '📄';
    if (actionBtn) actionBtn.textContent = TL('📋 View Prescriptions', '📋 ప్రిస్క్రిప్షన్లు చూడండి', '📋 पर्चा देखें');
  } else if (payload.type === 'order_created') {
    if (appNameEl) appNameEl.textContent = TL('🛒 AGRI-STORE ORDER', '🛒 మందుల ఆర్డర్ కన్ఫర్మ్', '🛒 दवा ऑर्डर पुष्टि');
    if (iconEl) iconEl.textContent = '🛒';
    if (actionBtn) actionBtn.textContent = TL('📦 View in Farm Khata', '📦 ఖాతాలో చూడండి', '📦 खाते में देखें');
  } else if (payload.type === 'price_surge') {
    if (appNameEl) appNameEl.textContent = TL('🚨 NUKROP LIVE SURGE TRIGGER', '🚨 లైవ్ ధర పెరుగుదల హెచ్చరిక', '🚨 लाइव भाव वृद्धि अलर्ट');
    if (iconEl) iconEl.textContent = '📈';
    if (actionBtn) actionBtn.textContent = TL('🚚 Book Mandi Truck', '🚚 మండి ట్రక్ బుక్ చేయండి', '🚚 मंडी ट्रक बुक करें');
  } else {
    if (appNameEl) appNameEl.textContent = TL('🔔 NUKROP AGRI ALERT', '🔔 వ్యవసాయ హెచ్చరిక', '🔔 कृषि अलर्ट');
    if (iconEl) iconEl.textContent = '🔔';
    if (actionBtn) actionBtn.textContent = TL('🔔 View Alerts', '🔔 అలర్ట్స్ చూడండి', '🔔 अलर्ट देखें');
  }

  toast.style.display = 'block';

  if (pushToastTimeout) clearTimeout(pushToastTimeout);
  pushToastTimeout = setTimeout(() => {
    dismissPushToast();
  }, 7000);
}

function handleDynamicToastAction() {
  dismissPushToast();
  if (!lastToastPayload) return;

  if (lastToastPayload.type === 'prescription_saved') {
    openSavedPrescriptionsModal();
  } else if (lastToastPayload.type === 'order_created') {
    openScreen('khata', null);
    syncSideNav('btn-khata');
  } else if (lastToastPayload.type === 'price_surge') {
    openScreen('gramhaul', null);
    syncSideNav('btn-gramhaul');
  } else {
    openPriceAlertModal(null, 'feed');
  }
}


function dismissPushToast() {
  const toast = document.getElementById('global-push-toast');
  if (toast) toast.style.display = 'none';
  if (pushToastTimeout) clearTimeout(pushToastTimeout);
}

function handlePushToastClick() {
  if (lastToastPayload && lastToastPayload.type === 'price_surge') {
    onToastActionBookTruck();
  } else {
    dismissPushToast();
  }
}

function onToastActionBookTruck() {
  dismissPushToast();
  openScreen('gramhaul', null);
  syncSideNav('btn-truck');
}

