function getMandiDefaults(slug) {
  const clean = (slug || 'cotton').toLowerCase().trim();

  // Find corresponding item in AGMARKNET_MANDI_CATALOG
  let found = AGMARKNET_MANDI_CATALOG.find(x => {
    if (!x) return false;
    if (x.cropSlug === clean || x.cropKey === clean) return true;
    if ((clean.includes('chili') || clean.includes('chilli') || clean.includes('pepper')) && (x.cropKey === 'chilli' || x.cropSlug === 'birds-eye-chili')) return true;
    if (clean.includes('cotton') && x.cropKey === 'cotton') return true;
    if ((clean.includes('rice') || clean.includes('paddy')) && (x.cropKey === 'rice' || x.cropSlug === 'rice')) return true;
    if (clean.includes('wheat') && x.cropKey === 'wheat') return true;
    if (clean.includes('tomato') && x.cropKey === 'tomato') return true;
    if (clean.includes('onion') && x.cropKey === 'onion') return true;
    if (clean.includes('potato') && x.cropKey === 'potato') return true;
    return false;
  });

  if (!found) {
    found = AGMARKNET_MANDI_CATALOG.find(x => x.cropKey === 'cotton') || AGMARKNET_MANDI_CATALOG[0];
  }

  return {
    mandiObj: found.mandi,
    price: '₹' + Number(found.modalPrice).toLocaleString('en-IN'),
    rawPrice: found.modalPrice,
    unit: found.unit || '/Qtl',
    change: found.change ? (found.change.includes('+') || found.change.includes('-') ? found.change : (found.up ? '+' + found.change : '-' + found.change)) : '+₹140 ▲',
    up: found.up !== false,
    mandiId: found.id,
    catalogItem: found
  };
}

function refreshMandiRatesLive() {
  const priceEl = document.getElementById('home-mandi-live-price');
  const changeEl = document.getElementById('home-mandi-live-change');
  const cardEl = document.getElementById('home-mandi-card-container');
  const btnEl = document.getElementById('home-mandi-refresh-btn');

  if (btnEl) {
    btnEl.style.transform = 'rotate(360deg)';
    btnEl.style.transition = 'transform 0.6s ease';
    setTimeout(() => {
      btnEl.style.transform = 'rotate(0deg)';
      btnEl.style.transition = 'none';
    }, 650);
  }

  if (!priceEl) return;

  const currentCrop = myActiveCrops[activeCropIdx] || myActiveCrops[0];
  const mandiInfo = getMandiDefaults(currentCrop.id);

  const delta = Math.floor(Math.random() * 50) + 15;
  const isUp = Math.random() > 0.2;
  const newPrice = isUp ? mandiInfo.rawPrice + delta : Math.max(500, mandiInfo.rawPrice - delta);

  priceEl.innerHTML = '₹' + newPrice.toLocaleString('en-IN') + ' <span style="font-size:10px;color:#64748B;font-weight:600;">' + mandiInfo.unit + '</span>';
  if (changeEl) {
    changeEl.innerHTML = (isUp ? 'today +₹' + delta : 'today -₹' + delta) + (isUp ? ' ▲' : ' ▼');
    changeEl.style.color = isUp ? '#16A34A' : '#DC2626';
  }

  if (cardEl) {
    cardEl.style.transition = 'all 0.35s ease';
    cardEl.style.boxShadow = '0 0 0 3px #86EFAC, 0 8px 24px rgba(22,163,74,0.18)';
    setTimeout(() => {
      cardEl.style.boxShadow = '0 4px 16px -2px rgba(234,88,12,0.12), 0 2px 6px rgba(0,0,0,0.03)';
    }, 800);
  }
}


