function getAstronomicalState() {
  const now = new Date();
  const mins = now.getHours() * 60 + now.getMinutes();
  const sunriseMins = 5 * 60 + 57; // 05:57 AM = 357
  const sunsetMins = 18 * 60 + 26; // 06:26 PM = 1106
  const isDay = mins >= sunriseMins && mins <= sunsetMins;

  let progress = 0.5;
  let phase = 'day';
  let badge = {
    en: '☀️ DAYLIGHT', te: '☀️ పగటి సమయం', hi: '☀️ दिन का समय',
    ta: '☀️ பகல் நேரம்', kn: '☀️ ಹಗಲು ಸಮಯ', ml: '☀️ പകൽ സമയം',
    mr: '☀️ दिवसाची वेळ', bn: '☀️ দিনের সময়', gu: '☀️ દિવસનો સમય',
    pa: '☀️ ਦਿਨ ਦਾ ਸਮਾਂ', or: '☀️ ଦିନ ସମୟ'
  };

  if (isDay) {
    progress = (mins - sunriseMins) / (sunsetMins - sunriseMins);
    if (mins <= sunriseMins + 45) {
      phase = 'sunrise';
      badge = {
        en: '🌅 SUNRISE', te: '🌅 సూర్యోదయం', hi: '🌅 सूर्योदय',
        ta: '🌅 சூரிய உதயம்', kn: '🌅 ಸೂರ್ಯೋದಯ', ml: '🌅 സൂര്യോദയം',
        mr: '🌅 सूर्योदय', bn: '🌅 সূর্যোদয়', gu: '🌅 સૂર્યોદય',
        pa: '🌅 ਸੂਰਜ ਚੜ੍ਹਨਾ', or: '🌅 ସୂର୍ଯ୍ୟୋଦୟ'
      };
    } else if (mins >= sunsetMins - 45) {
      phase = 'sunset';
      badge = {
        en: '🌇 SUNSET', te: '🌇 సూర్యాస్తమయం', hi: '🌇 सूर्यास्त',
        ta: '🌇 சூரிய அஸ்தமனம்', kn: '🌇 ಸೂರ್ಯಾಸ್ತ', ml: '🌇 സൂര്യാസ്തമയം',
        mr: '🌇 सूर्यास्त', bn: '🌇 সূর্যাস্ত', gu: '🌇 સૂર્યાસ્ત',
        pa: '🌇 ਸੂਰਜ ਡੁੱਬਣਾ', or: '🌇 ସୂର୍ଯ୍ୟାସ୍ତ'
      };
    }
  } else {
    phase = 'night';
    const nightDuration = (24 * 60) - (sunsetMins - sunriseMins);
    const nightElapsed = mins > sunsetMins ? (mins - sunsetMins) : ((1440 - sunsetMins) + mins);
    progress = Math.min(Math.max(nightElapsed / nightDuration, 0.05), 0.95);
    badge = {
      en: '🌙 NIGHT TIME', te: '🌙 రాత్రి సమయం', hi: '🌙 रात्रि समय',
      ta: '🌙 இரவு நேரம்', kn: '🌙 ರಾತ್ರಿ ಸಮಯ', ml: '🌙 രാത്രി സമയം',
      mr: '🌙 रात्र वेळ', bn: '🌙 রাতের সময়', gu: '🌙 રાત્રિ સમય',
      pa: '🌙 ਰਾਤ ਦਾ ਸਮਾਂ', or: '🌙 ରାତି ସମୟ'
    };
  }

  const p = Math.min(Math.max(progress, 0.02), 0.98);
  // Quadratic bezier curve M 30 26 Q 150 2 270 26
  const cx = (1-p)*(1-p)*30 + 2*(1-p)*p*150 + p*p*270;
  const cy = (1-p)*(1-p)*26 + 2*(1-p)*p*2 + p*p*26;

  return { isDay, phase, progress: p, cx, cy, badge };
}

