function refreshWeatherData() {
  const icon = document.getElementById('w-refresh-icon');
  if (icon) {
    icon.classList.add('spin-anim');
    setTimeout(() => icon.classList.remove('spin-anim'), 750);
  }

  // Update real-time variance
  liveWeather.humidity = Math.min(Math.max(liveWeather.humidity + Math.floor(Math.random()*5 - 2), 65), 85);
  liveWeather.wind = Math.min(Math.max(parseInt(liveWeather.wind) + Math.floor(Math.random()*3 - 1), 6), 14).toString();

  // Re-render home screen cleanly
  openScreen('home', document.getElementById('tab-home'));
}





