function openEditProfileModal() {
  const modal = document.getElementById('profile-edit-modal');
  if (!modal) return;

  const nameInput = document.getElementById('edit-prof-name');
  const phoneInput = document.getElementById('edit-prof-phone');
  const villageInput = document.getElementById('edit-prof-village');
  const landInput = document.getElementById('edit-prof-land');

  if (nameInput) nameInput.value = farmerProfile.name[currentLang] || farmerProfile.name.en;
  if (phoneInput) phoneInput.value = farmerProfile.phone;
  if (villageInput) villageInput.value = farmerProfile.village[currentLang] || farmerProfile.village.en;
  if (landInput) landInput.value = farmerProfile.landAcres;

  modal.style.display = 'flex';
}

function closeEditProfileModal() {
  const modal = document.getElementById('profile-edit-modal');
  if (modal) modal.style.display = 'none';
}

function saveFarmerProfile() {
  const nameInput = document.getElementById('edit-prof-name');
  const phoneInput = document.getElementById('edit-prof-phone');
  const villageInput = document.getElementById('edit-prof-village');
  const landInput = document.getElementById('edit-prof-land');

  if (nameInput && nameInput.value.trim()) {
    farmerProfile.name[currentLang] = nameInput.value.trim();
    farmerProfile.name.en = nameInput.value.trim();
  }
  if (phoneInput && phoneInput.value.trim()) farmerProfile.phone = phoneInput.value.trim();
  if (villageInput && villageInput.value.trim()) {
    farmerProfile.village[currentLang] = villageInput.value.trim();
    farmerProfile.village.en = villageInput.value.trim();
  }
  if (landInput && landInput.value.trim()) farmerProfile.landAcres = landInput.value.trim();

  closeEditProfileModal();
  openScreen('profile', document.getElementById('tab-profile'));
  alert(currentLang === 'te' ? '✅ రైతు ప్రొఫైల్ వివరాలు విజయవంతంగా భద్రపరచబడ్డాయి!' : (currentLang === 'hi' ? '✅ किसान प्रोफाइल सफलतापूर्वक अपडेट की गई!' : '✅ Farmer Profile updated successfully!'));
}

function toggleProfileSetting(key) {
  if (key === 'voice') {
    farmerProfile.voiceEnabled = !farmerProfile.voiceEnabled;
    alert(farmerProfile.voiceEnabled
      ? (currentLang === 'te' ? '🔊 వాయిస్ అసిస్టెంట్ ఆన్ చేయబడింది' : '🔊 Voice Assistant Enabled')
      : (currentLang === 'te' ? '🔇 వాయిస్ అసిస్టెంట్ ఆఫ్ చేయబడింది' : '🔇 Voice Assistant Muted'));
  } else if (key === 'weather') {
    farmerProfile.weatherAlerts = !farmerProfile.weatherAlerts;
    alert(farmerProfile.weatherAlerts
      ? (currentLang === 'te' ? '🔔 తీవ్ర వాతావరణ అలర్ట్‌లు యాక్టివ్ చేయబడ్డాయి' : '🔔 Extreme Weather & Pest Alerts Enabled')
      : (currentLang === 'te' ? '🔕 అలర్ట్‌లు నిలిపివేయబడ్డాయి' : '🔕 Weather Alerts Paused'));
  } else if (key === 'biometric') {
    farmerProfile.biometricLock = !farmerProfile.biometricLock;
    alert(farmerProfile.biometricLock
      ? (currentLang === 'te' ? '🔒 బయోమెట్రిక్ ఫింగర్‌ప్రింట్ లాక్ ఆన్ చేయబడింది' : '🔒 Biometric Fingerprint Lock Enabled')
      : (currentLang === 'te' ? '🔓 బయోమెట్రిక్ లాక్ ఆఫ్ చేయబడింది' : '🔓 Biometric Lock Disabled'));
  }
  openScreen('profile', document.getElementById('tab-profile'));
}

