function getMachineryIllustrationSvg(type) {
  const t = (type || '').toLowerCase();
  if (t.includes('drone')) {
    return `
      <div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#EFF6FF,#DBEAFE);border-radius:14px;">
        <svg width="42" height="42" viewBox="0 0 24 24" fill="none" stroke="#2563EB" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">
          <path d="M12 12m-3 0a3 3 0 1 0 6 0a3 3 0 1 0 -6 0"/>
          <path d="M7 7l10 10"/><path d="M17 7l-10 10"/>
          <circle cx="5" cy="5" r="2.5" fill="#BFDBFE"/>
          <circle cx="19" cy="5" r="2.5" fill="#BFDBFE"/>
          <circle cx="5" cy="19" r="2.5" fill="#BFDBFE"/>
          <circle cx="19" cy="19" r="2.5" fill="#BFDBFE"/>
          <path d="M12 15v4m-2 0h4"/>
        </svg>
      </div>
    `;
  }
  if (t.includes('harvester')) {
    return `
      <div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#FEF3C7,#FDE68A);border-radius:14px;">
        <svg width="42" height="42" viewBox="0 0 24 24" fill="none" stroke="#D97706" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">
          <circle cx="6" cy="18" r="3" fill="#FCD34D"/>
          <circle cx="17" cy="18" r="2.5" fill="#FCD34D"/>
          <path d="M3 15h18v-4l-3-4H8L5 11v4z"/>
          <path d="M2 13h4v3H2z"/><path d="M18 10l3 3"/>
        </svg>
      </div>
    `;
  }
  if (t.includes('spray')) {
    return `
      <div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#ECFDF5,#D1FAE5);border-radius:14px;">
        <svg width="42" height="42" viewBox="0 0 24 24" fill="none" stroke="#059669" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">
          <rect x="6" y="7" width="12" height="12" rx="3" fill="#A7F3D0"/>
          <path d="M10 4h4v3h-4z"/><path d="M12 2v2"/>
          <path d="M18 10l3-2v6l-3-2"/><path d="M6 10L3 8v6l3-2"/>
        </svg>
      </div>
    `;
  }
  // Default Tractor
  return `
    <div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#DCFCE7,#BBF7D0);border-radius:14px;">
      <svg width="42" height="42" viewBox="0 0 24 24" fill="none" stroke="#15803D" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">
        <circle cx="6" cy="17" r="3.5" fill="#86EFAC"/>
        <circle cx="18" cy="17" r="2.5" fill="#86EFAC"/>
        <path d="M6 13.5h7l2-5h-4l-2 3H3v2h3z"/>
        <path d="M15 13.5h3.5l2.5 3.5"/>
        <path d="M8 8V4h2v4"/>
      </svg>
    </div>
  `;
}


