function renderMachineryCardHtml(item) {
  const nameStr = (item.name && (item.name[currentLang] || item.name.en)) || item.name;
  const ownerStr = (item.owner && (item.owner[currentLang] || item.owner.en)) || item.owner;
  const hubStr = (item.hub && (item.hub[currentLang] || item.hub.en)) || item.hub || 'Local Agrarian Hub';
  const distStr = (item.dist && (item.dist[currentLang] || item.dist.en)) || item.dist || '2 km away';
  const specsStr = (item.specs && (item.specs[currentLang] || item.specs.en)) || item.specs;
  const callBtn = TL('📞 Call', '📞 కాల్', '📞 कॉल');
  const bookNowBtn = TL('⚡ Book Now', '⚡ ఇప్పుడే బుక్ చేయండి', '⚡ अभी बुक करें');

  return `
    <div class="m3-card" style="padding:14px;margin-bottom:14px;background:#FFFFFF;border:1.2px solid #E2ECE2;border-radius:18px;box-shadow:0 3px 12px rgba(0,0,0,0.03);">
      <div style="display:flex;gap:12px;margin-bottom:10px;">
        <div style="width:78px;height:78px;flex-shrink:0;border-radius:14px;overflow:hidden;border:1px solid #E2E8F0;background:#F1F5F9;">
          <img src="${item.photoUrl || 'https://images.unsplash.com/photo-1592982537447-7440770cbfc9?w=400&auto=format&fit=crop&q=80'}" alt="${nameStr}" style="width:100%;height:100%;object-fit:cover;border-radius:12px;" onerror="this.outerHTML=getMachineryIllustrationSvg('${item.category}')">
        </div>
        <div style="flex:1;min-width:0;">
          <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:4px;">
            <div style="font-size:13.5px;font-weight:900;color:#0F172A;line-height:1.3;">${nameStr}</div>
            <span style="background:#DCFCE7;color:#15803D;font-size:9.5px;font-weight:900;padding:2px 7px;border-radius:8px;border:1px solid #86EFAC;flex-shrink:0;">
              ⚡ ${TL('Available', 'అందుబాటులో ఉంది', 'उपलब्ध')}
            </span>
          </div>
          <div style="font-size:11px;color:#64748B;font-weight:700;margin-top:2px;">📍 ${hubStr} · ${distStr}</div>
          <div style="font-size:11px;color:#D97706;font-weight:800;margin-top:1px;">${item.rating}</div>
        </div>
      </div>

      <div style="background:#F8FAFC;padding:8px 10px;border-radius:10px;font-size:11px;color:#475569;font-weight:600;margin-bottom:12px;line-height:1.4;border:1px solid #F1F5F9;">
        ${specsStr}
      </div>

      <div style="display:flex;justify-content:space-between;align-items:center;border-top:1px solid #F1F5F9;padding-top:10px;">
        <div>
          <span style="font-size:15px;font-weight:900;color:#1B5E20;">₹${item.hourlyRate}</span>
          <span style="font-size:10.5px;color:#64748B;font-weight:700;"> / ${TL('hr', 'గంట', 'घंटा')}</span>
          ${item.acreRate ? `<span style="font-size:11px;color:#64748B;margin-left:4px;">(₹${item.acreRate}/${TL('ac', 'ఎక.', 'एक.')})</span>` : ''}
        </div>
        <div style="display:flex;gap:6px;">
          <button onclick="callEquipmentOwner('${item.id}')" style="background:#F1F5F9;color:#334155;border:1px solid #CBD5E1;border-radius:10px;padding:6px 11px;font-size:11px;font-weight:800;cursor:pointer;">
            ${callBtn}
          </button>
          <button onclick="openMachineryBookingModal('${item.id}')" style="background:#1B5E20;color:#FFFFFF;border:none;border-radius:10px;padding:6px 13px;font-size:11px;font-weight:800;cursor:pointer;box-shadow:0 2px 6px rgba(27,94,32,0.25);">
            ${bookNowBtn}
          </button>
        </div>
      </div>
    </div>
  `;
}

function setMachineryFilter(catKey) {
  currentMachineryFilter = catKey;
  if (typeof openScreen === 'function') {
    openScreen('equipment', document.getElementById('tab-equipment'));
  }
}

function filterMachinerySearch(query) {
  currentMachinerySearchQuery = (query || '').toLowerCase().trim();
  const listContainer = document.getElementById('machinery-list-container');
  if (!listContainer) return;

  const filtered = MACHINERY_CATALOG.filter(m => {
    const matchCat = currentMachineryFilter === 'all' || m.category === currentMachineryFilter;
    if (!matchCat) return false;
    if (!currentMachinerySearchQuery) return true;
    const nameStr = ((m.name && (m.name[currentLang] || m.name.en)) || m.name || '').toLowerCase();
    const specsStr = ((m.specs && (m.specs[currentLang] || m.specs.en)) || m.specs || '').toLowerCase();
    const hubStr = ((m.hub && (m.hub[currentLang] || m.hub.en)) || m.hub || '').toLowerCase();
    return nameStr.includes(currentMachinerySearchQuery) || specsStr.includes(currentMachinerySearchQuery) || hubStr.includes(currentMachinerySearchQuery);
  });

  if (filtered.length === 0) {
    listContainer.innerHTML = `
      <div style="text-align:center;padding:40px 20px;background:#FFFFFF;border:1.5px dashed #CBD5E1;border-radius:18px;">
        <div style="font-size:36px;margin-bottom:8px;">🚜</div>
        <div style="font-size:14px;font-weight:900;color:#0F172A;margin-bottom:4px;">${TL('No machinery matches your search', 'మీ శోధనకు తగిన యంత్రాలు లేవు', 'आपकी खोज के लिए कोई उपकरण उपलब्ध नहीं है')}</div>
        <div style="font-size:11px;color:#64748B;margin-bottom:12px;">${TL('Try searching for tractors, drones or harvesters in nearby hubs', 'సమీప కేంద్రాల్లో ట్రాక్టర్లు లేదా డ్రోన్లను వెతకండి', 'पास के केंद्रों में ट्रैक्टर या ड्रोन खोजें')}</div>
        <button onclick="setMachineryFilter('all')" style="background:#15803D;color:#FFFFFF;border:none;border-radius:20px;padding:7px 16px;font-size:11px;font-weight:800;cursor:pointer;">
          ${TL('Show All Equipment', 'అన్ని యంత్రాలు చూపించు', 'सभी उपकरण देखें')}
        </button>
      </div>
    `;
  } else {
    listContainer.innerHTML = filtered.map(item => renderMachineryCardHtml(item)).join('');
  }
}

let selectedBookingMachine = null;
let currentBookingUnit = 'acre'; // 'acre' | 'hour'
let currentBookingQty = 2;

