function submitMachineryListing() {
  const nameInput = document.getElementById('new-mach-name');
  const catInput = document.getElementById('new-mach-cat');
  const hourlyInput = document.getElementById('new-mach-hourly');
  const acreInput = document.getElementById('new-mach-acre');
  const hubInput = document.getElementById('new-mach-hub');
  const phoneInput = document.getElementById('new-mach-phone');
  const specsInput = document.getElementById('new-mach-specs');

  const nameVal = nameInput ? nameInput.value.trim() : '';
  if (!nameVal) {
    alert(TL('Please enter your equipment make and model!', 'దయచేసి మీ యంత్రం పేరు మరియు మోడల్ రాయండి!', 'कृपया उपकरण का नाम और मॉडल लिखें!'));
    return;
  }

  const category = catInput ? catInput.value : 'tractor';
  const hourly = parseInt(hourlyInput?.value || '700', 10);
  const acre = parseInt(acreInput?.value || '1100', 10);
  const hub = hubInput ? hubInput.value.trim() : 'Local Hub';
  const phone = phoneInput ? phoneInput.value.trim() : '+91 98490 22338';
  const specs = specsInput ? specsInput.value.trim() : 'Verified Implement';

  const defaultPhotos = {
    tractor: 'https://images.unsplash.com/photo-1592982537447-7440770cbfc9?w=400&auto=format&fit=crop&q=80',
    drone: 'https://images.unsplash.com/photo-1508614589041-895b88991e3e?w=400&auto=format&fit=crop&q=80',
    harvester: 'https://images.unsplash.com/photo-1595974482597-4b8da8879bc5?w=400&auto=format&fit=crop&q=80',
    sprayer: 'https://images.unsplash.com/photo-1628352081506-83c43123ed6d?w=400&auto=format&fit=crop&q=80'
  };

  const newItem = {
    id: 'mach-custom-' + Date.now(),
    name: { en: nameVal, te: nameVal, hi: nameVal },
    category: category,
    hourlyRate: hourly,
    acreRate: acre,
    rating: '⭐ 5.0 (New Listing)',
    hub: { en: hub, te: hub, hi: hub },
    dist: { en: '0.8 km (Your Village)', te: '0.8 కి.మీ (మీ గ్రామం)', hi: '0.8 किमी (आपका गांव)' },
    owner: { en: 'B. Jaswanth Reddy (You)', te: 'బి. జస్వంత్ రెడ్డి (మీరు)', hi: 'बी. जसवंत रेड्डी (आप)' },
    phone: phone,
    photoUrl: defaultPhotos[category] || defaultPhotos.tractor,
    specs: { en: specs, te: specs, hi: specs }
  };

  MACHINERY_CATALOG.unshift(newItem);
  closeMachineryListingModal(null);

  alert(TL(
    '🎉 Equipment Listed Successfully!\n\n' + nameVal + ' is now active on the NuKrop Hub for local farmers to rent.',
    '🎉 మీ యంత్రం విజయవంతంగా జాబితాలో చేర్చబడింది!\n\nస్థానిక రైతులు దీనిని ఇప్పుడు అద్దెకు బుక్ చేసుకోవచ్చు.',
    '🎉 आपका उपकरण सफलतापूर्वक जुड़ गया!\n\nस्थानीय किसान अब इसे किराए पर बुक कर सकते हैं।'
  ));

  if (typeof openScreen === 'function') openScreen('equipment', document.getElementById('tab-equipment'));
}

function closeMachineryListingModal(e) {
  const modal = document.getElementById('machinery-listing-modal');
  if (modal) modal.style.display = 'none';
}

function callEquipmentOwner(itemId) {
  const item = MACHINERY_CATALOG.find(m => m.id === itemId) || MACHINERY_CATALOG[0];
  const cleanPhone = (item.phone || '9848022338').replace(/[^0-9+]/g, '');
  const ownerName = (item.owner && (item.owner[currentLang] || item.owner.en)) || item.owner || 'Equipment Owner';
  const modelName = (item.name && (item.name[currentLang] || item.name.en)) || item.name || 'Machinery';

  const promptText = TL(
    '📞 Contact Machinery Owner:\n' + ownerName + ' (' + modelName + ')\n\nPhone: ' + cleanPhone,
    '📞 యజమాని సంప్రదింపు వివరాలు:\n' + ownerName + ' (' + modelName + ')\n\nఫోన్: ' + cleanPhone,
    '📞 उपकरण मालिक संपर्क:\n' + ownerName + ' (' + modelName + ')\n\nफोन: ' + cleanPhone
  );

  const choice = confirm(promptText + '\n\nPress OK to open Phone Dialer, or Cancel to open WhatsApp.');
  if (choice) {
    window.location.href = 'tel:' + cleanPhone;
  } else {
    window.open('https://wa.me/' + cleanPhone.replace('+', '') + '?text=' + encodeURIComponent('Namaste, I want to rent ' + modelName + ' via NuKropAI OS.'), '_blank');
  }
}

