function setKhataEntryType(type) {
  currentKhataEntryType = type;
  const btnExp = document.getElementById('ke-btn-expense');
  const btnInc = document.getElementById('ke-btn-income');
  const selCat = document.getElementById('ke-category-select');
  const descInp = document.getElementById('ke-desc-input');

  if (type === 'income') {
    if (btnInc) { btnInc.style.background = '#15803D'; btnInc.style.color = '#FFFFFF'; }
    if (btnExp) { btnExp.style.background = '#FFFFFF'; btnExp.style.color = '#DC2626'; }
    if (descInp) descInp.placeholder = TL('e.g. Cotton Sale 6.5 Qtl Warangal APMC', 'ఉదా: వరంగల్ యార్డ్‌లో 6.5 క్వింటాళ్ల పత్తి అమ్మకం', 'उदा: कपास 6.5 क्विंटल वारंगल मंडी बिक्री');
  } else {
    if (btnExp) { btnExp.style.background = '#DC2626'; btnExp.style.color = '#FFFFFF'; }
    if (btnInc) { btnInc.style.background = '#FFFFFF'; btnInc.style.color = '#15803D'; }
    if (descInp) descInp.placeholder = TL('e.g. DAP 2 Bags, Drone Spray Charges', 'ఉదా: DAP ఎరువుల బస్తాలు 2, డ్రోన్ పిచికారీ', 'उदा: डीएपी खाद 2 बोरी, ड्रोन छिड़काव');
  }
  if (selCat) selCat.innerHTML = getKhataCategoryOptionsHtml(type);
}

