function selectOnboardingLang(langCode) {
  onboardingState.lang = langCode;
  if (typeof setLanguage === 'function') setLanguage(langCode);
  nextOnboardingStep();
}

function selectOnboardingCrop(cropKey, cropDisplayName) {
  onboardingState.crop = cropKey;
  onboardingState.cropName = cropDisplayName;
  nextOnboardingStep();
}

function selectOnboardingGoal(goalKey, goalTitle) {
  onboardingState.goal = goalKey;
  onboardingState.goalTitle = goalTitle;
  nextOnboardingStep();
}

function nextOnboardingStep() {
  if (onboardingState.step < onboardingState.totalSteps) {
    onboardingState.step++;
    renderOnboardingStep();
  } else {
    finishOnboarding();
  }
}

function prevOnboardingStep() {
  if (onboardingState.step > 1) {
    onboardingState.step--;
    renderOnboardingStep();
  }
}

function skipOnboarding() {
  NuKropAnalytics.track('onboarding_skipped', { fromStep: onboardingState.step });
  finishOnboarding(true);
}

function finishOnboarding(isGuest = false) {
  NuKropAnalytics.track('onboarding_completed', {
    lang: onboardingState.lang,
    crop: onboardingState.crop,
    goal: onboardingState.goal,
    isGuest
  });

  localStorage.setItem('nukrop_onboarding_v2_completed', 'true');

  const overlay = document.getElementById('onboarding-experience-overlay');
  if (overlay) {
    overlay.style.transition = 'opacity 0.25s ease, transform 0.25s ease';
    overlay.style.opacity = '0';
    overlay.style.transform = 'scale(0.96)';
    setTimeout(() => overlay.remove(), 250);
  }

  let stOverlay = document.getElementById('startup-experience-overlay');
  if (!stOverlay) {
    const chassis = document.querySelector('.phone-chassis') || document.body;
    stOverlay = document.createElement('div');
    stOverlay.id = 'startup-experience-overlay';
    stOverlay.style.cssText = 'position:fixed;inset:0;background:#FFFFFF;z-index:99999;display:flex;flex-direction:column;';
    chassis.appendChild(stOverlay);
  }
  renderLoginScreen(stOverlay);
}







