// ── OFFICIAL NUKROPAI LOGO ASSET ──
const NUKROP_LOGO_DATA_URI = 'data:image/png;base64,';

function getNukropLogoImg(heightPx = 42, styleExtra = '') {
  return `<img src="${NUKROP_LOGO_DATA_URI}" alt="NuKropAI" style="height:${heightPx}px;max-width:240px;object-fit:contain;display:inline-block;${styleExtra}">`;
}


