function get4kLeafSvg(sizePx = 44) {
  return `
    <svg width="${sizePx}" height="${sizePx}" viewBox="0 0 100 100" fill="none" xmlns="http://www.w3.org/2000/svg" style="display:inline-block;vertical-align:middle;filter:drop-shadow(0 3px 6px rgba(16,185,129,0.32));">
      <defs>
        <linearGradient id="nukropLeafGradExact" x1="18" y1="82" x2="82" y2="18" gradientUnits="userSpaceOnUse">
          <stop offset="0%" stop-color="#059669"/>
          <stop offset="28%" stop-color="#10B981"/>
          <stop offset="68%" stop-color="#22C55E"/>
          <stop offset="100%" stop-color="#4ADE80"/>
        </linearGradient>
        <filter id="leafGlowExact" x="0" y="0" width="100" height="100" filterUnits="userSpaceOnUse">
          <feDropShadow dx="0" dy="0" stdDeviation="1.2" flood-color="#FFFFFF" flood-opacity="0.9"/>
        </filter>
      </defs>

      <!-- Exact Botanical Leaf Contour (matching media_1788415051841.png) -->
      <path d="M 18 82 
               C 13 54, 38 22, 82 18 
               C 87 46, 62 78, 18 82 Z" 
            fill="url(#nukropLeafGradExact)"/>

      <!-- Clean Crisp White Center Vein -->
      <path d="M 22 78 Q 48 48 78 22" 
            stroke="#FFFFFF" 
            stroke-width="3.8" 
            stroke-linecap="round" 
            filter="url(#leafGlowExact)"/>

      <!-- Water Droplet 1 -->
      <circle cx="58" cy="42" r="3.4" stroke="#D1FAE5" stroke-width="1.3" fill="rgba(255,255,255,0.45)"/>
      <circle cx="57" cy="41" r="1" fill="#FFFFFF"/>

      <!-- Water Droplet 2 -->
      <circle cx="47" cy="54" r="2.6" stroke="#D1FAE5" stroke-width="1.2" fill="rgba(255,255,255,0.45)"/>
      <circle cx="46.2" cy="53.2" r="0.8" fill="#FFFFFF"/>
    </svg>
  `;
}


