// AUTHENTICATION & LOGIN STATE CONTROLLERS
// ══════════════════════════════════════════════════════
let authUserRole = 'farmer'; // 'farmer' or 'driver'
let authFormMode = 'signup'; // 'signup' or 'signin'
let passwordVisible = false;

function setAuthUserRole(role) {
  authUserRole = role;
  const overlay = document.getElementById('startup-experience-overlay') || document.getElementById('login-screen-overlay') || document.getElementById('screen-body');
  if (overlay) renderLoginScreen(overlay);
}

function setAuthFormMode(mode) {
  authFormMode = mode;
  const overlay = document.getElementById('startup-experience-overlay') || document.getElementById('login-screen-overlay') || document.getElementById('screen-body');
  if (overlay) renderLoginScreen(overlay);
}

function togglePasswordVisibility() {
  passwordVisible = !passwordVisible;
  const inp = document.getElementById('auth-password-input');
  if (inp) {
    inp.type = passwordVisible ? 'text' : 'password';
  }
}



function loginAsDriver() {
  const nameInp = document.getElementById('drv-login-name');
  const phoneInp = document.getElementById('drv-login-phone');
  const plateInp = document.getElementById('drv-login-plate');
  const vehicleInp = document.getElementById('drv-login-vehicle');

  const driverName = (nameInp && nameInp.value.trim()) || localStorage.getItem('nukrop_driver_name') || 'Registered Driver';
  const driverPhone = (phoneInp && phoneInp.value.trim()) || localStorage.getItem('nukrop_driver_phone') || '+91 98490 22338';
  const driverPlate = (plateInp && plateInp.value.trim()) || localStorage.getItem('nukrop_driver_plate') || 'TS-03-UB-4491';
  const vehicleType = (vehicleInp && vehicleInp.value) || 'Tata Ace (1.5 Ton)';

  localStorage.setItem('nukrop_user_role', 'driver');
  localStorage.setItem('nukrop_driver_name', driverName);
  localStorage.setItem('nukrop_driver_phone', driverPhone);
  localStorage.setItem('nukrop_driver_plate', driverPlate);
  localStorage.setItem('nukrop_driver_vehicle', vehicleType);

  if (typeof GRAMHAUL_POOLED_TRUCKS !== 'undefined' && GRAMHAUL_POOLED_TRUCKS.length > 0) {
    GRAMHAUL_POOLED_TRUCKS[0].driverName = driverName;
    GRAMHAUL_POOLED_TRUCKS[0].driverPhone = driverPhone;
    GRAMHAUL_POOLED_TRUCKS[0].plate = driverPlate;
    GRAMHAUL_POOLED_TRUCKS[0].vehicle = vehicleType;
  }

  const ids = ['startup-experience-overlay', 'onboarding-experience-overlay', 'splash-viewport', 'login-screen-overlay'];
  ids.forEach(id => {
    const el = document.getElementById(id);
    if (el) el.remove();
  });

  if (typeof showLuxuryToast === 'function') {
    showLuxuryToast('🚚 Welcome to GramHaul, ' + driverName + '!', 'success');
  }
  openScreen('driver_dashboard', null);
}

function handleGuestLogin() {
  const ids = ['startup-experience-overlay', 'onboarding-experience-overlay', 'splash-viewport', 'login-screen-overlay'];
  ids.forEach(id => {
    const el = document.getElementById(id);
    if (el) el.remove();
  });
  openScreen('home', document.getElementById('tab-home'));
}

