function selectGoogleAccount(email, name) {
  const gModal = document.getElementById('google-auth-modal');
  if (gModal) gModal.remove();
  window.onNativeGoogleAccountSelected(email, name);
}

function promptForCustomGoogleAccount() {
  const customEmail = prompt("Enter your personal Google email address (e.g. name@gmail.com):", "");
  if (!customEmail || !customEmail.includes('@')) return;
  const customName = prompt("Enter your full name:", customEmail.split('@')[0]);
  selectGoogleAccount(customEmail.trim(), (customName || 'Registered User').trim());
}

function switchUserRole(role) {
  authUserRole = role;
  localStorage.setItem('nukrop_user_role', role);
  if (role === 'driver') {
    openScreen('driver_dashboard', null);
    if (typeof showLuxuryToast === 'function') showLuxuryToast('🚚 Switched to GramHaul Driver Cockpit', 'info');
  } else {
    openScreen('home', document.getElementById('tab-home'));
    if (typeof showLuxuryToast === 'function') showLuxuryToast('🧑‍🌾 Switched to Farmer Operations Hub', 'success');
  }
}

function toggleDriverOnlineStatus(btn) {
  if (!btn) return;
  const isOnline = btn.textContent.includes('ON');
  if (isOnline) {
    btn.textContent = 'Duty OFF';
    btn.style.background = '#64748B';
    if (typeof showLuxuryToast === 'function') showLuxuryToast('🔴 You are now OFFLINE. New haul broadcasts paused.', 'warning');
  } else {
    btn.textContent = 'Duty ON';
    btn.style.background = '#15803D';
    if (typeof showLuxuryToast === 'function') showLuxuryToast('🟢 You are now ONLINE! Receiving live farm haul bookings.', 'success');
  }
}

function acceptHaulBooking(haulId, amount) {
  if (typeof showLuxuryToast === 'function') {
    showLuxuryToast('✅ Haul #' + haulId + ' Accepted! (₹ ' + amount + ' UPI guaranteed on dropoff)', 'success');
  }
}

function completeGoogleAuth(email, name) {
  try {
    localStorage.setItem('nukrop_auth_method', 'google');
    localStorage.setItem('nukrop_user_email', email);
    localStorage.setItem('nukrop_user_name', name);
    if (typeof farmerProfile !== 'undefined') {
      farmerProfile.email = email;
    }
  } catch(e) {}

  NuKropAnalytics.track('login_google_success', { email, name });
  const modal = document.getElementById('google-auth-modal');
  if (modal) modal.remove();

  // Advance smoothly to language selection
  localStorage.setItem('nukrop_onboarding_plantix_completed', 'true');
  const overlay = document.getElementById('startup-experience-overlay');
  if (overlay) overlay.remove();
  openScreen('home', document.getElementById('tab-home'));
}

function handlePhoneAuth() {
  const phoneInp = document.getElementById('login-phone-input');
  if (phoneInp) loginPhoneValue = phoneInp.value.trim();

  if (!loginOtpSent) {
    loginOtpSent = true;
    const container = document.getElementById('startup-experience-overlay');
    if (container) renderLoginScreen(container);
    return;
  }

  // OTP Verified
  try {
    localStorage.setItem('nukrop_auth_method', 'phone_otp');
    localStorage.setItem('nukrop_user_phone', '+91 ' + loginPhoneValue);
    if (typeof farmerProfile !== 'undefined') {
      farmerProfile.phone = '+91 ' + loginPhoneValue;
    }
  } catch(e) {}

  NuKropAnalytics.track('login_phone_success', { phone: loginPhoneValue });
  localStorage.setItem('nukrop_onboarding_plantix_completed', 'true');
  const overlay = document.getElementById('startup-experience-overlay');
  if (overlay) overlay.remove();
  openScreen('home', document.getElementById('tab-home'));
}

function handleGuestLogin() {
  try {
    localStorage.setItem('nukrop_auth_method', 'guest');
  } catch(e) {}
  NuKropAnalytics.track('login_guest');
  localStorage.setItem('nukrop_onboarding_plantix_completed', 'true');
  const overlay = document.getElementById('startup-experience-overlay');
  if (overlay) overlay.remove();
  openScreen('home', document.getElementById('tab-home'));
}


