const SPEECH_LANG_MAP = {
  te: 'te-IN', hi: 'hi-IN', ta: 'ta-IN', kn: 'kn-IN', ml: 'ml-IN',
  mr: 'mr-IN', bn: 'bn-IN', gu: 'gu-IN', pa: 'pa-IN', or: 'or-IN', en: 'en-IN'
};

let activeSpeechUtterance = null;
let currentSpeakingBtn = null;

function stopSpeaking() {
  if (typeof window !== 'undefined' && window.speechSynthesis) {
    window.speechSynthesis.cancel();
  }
  if (currentSpeakingBtn) {
    currentSpeakingBtn.dataset.speaking = 'false';
    currentSpeakingBtn.innerHTML = '<span>🔊</span> ' + TL('Listen', 'వినండి', 'सुनें');
    currentSpeakingBtn.style.background = '#F0FDF4';
    currentSpeakingBtn.style.color = '#15803D';
    currentSpeakingBtn.style.borderColor = '#86EFAC';
    currentSpeakingBtn = null;
  }
}

function speakAiSpeech(text, btnElement) {
  if (typeof window === 'undefined' || !window.speechSynthesis) return;

  // Toggle off if already speaking
  if (window.speechSynthesis.speaking && currentSpeakingBtn === btnElement) {
    stopSpeaking();
    return;
  }

  stopSpeaking();

  const clean = text
    .replace(/\*\*(.*?)\*\*/g, '$1')
    .replace(/[#_*`]/g, '')
    .replace(/[🌿🐛📊🧪🏛️📍●•⚡💰🌾🚜👥💡🔍]/g, '')
    .replace(/\n+/g, '. ')
    .trim();

  const utter = new SpeechSynthesisUtterance(clean);
  const targetLocale = SPEECH_LANG_MAP[currentLang] || 'en-IN';
  utter.lang = targetLocale;
  utter.rate = 0.95;
  utter.pitch = 1.0;

  // Try to find native regional voice matching Indian locale
  try {
    const voices = window.speechSynthesis.getVoices();
    const bestVoice = voices.find(v => v.lang === targetLocale || v.lang.replace('_', '-') === targetLocale) ||
                      voices.find(v => v.lang.startsWith(targetLocale.split('-')[0])) ||
                      voices.find(v => v.lang.includes('IN')) ||
                      voices[0];
    if (bestVoice) utter.voice = bestVoice;
  } catch(e) {}

  if (btnElement) {
    currentSpeakingBtn = btnElement;
    btnElement.dataset.speaking = 'true';
    btnElement.innerHTML = '<span style="display:inline-flex;align-items:center;gap:3px;"><span style="width:5px;height:5px;border-radius:50%;background:#DC2626;animation:sunGlowPulse 0.8s infinite;"></span> ' + TL('Stop', 'ఆపండి', 'रोकें') + '</span>';
    btnElement.style.background = '#FEF2F2';
    btnElement.style.color = '#DC2626';
    btnElement.style.borderColor = '#FECACA';

    utter.onend = () => stopSpeaking();
    utter.onerror = () => stopSpeaking();
  }

  activeSpeechUtterance = utter;
  window.speechSynthesis.speak(utter);
}


function startVoiceInput() {
  const SpeechRec = (typeof window !== 'undefined') && (window.SpeechRecognition || window.webkitSpeechRecognition);
  const input = document.getElementById('ai-chat-input');
  const micBtn = document.getElementById('ai-voice-btn');

  if (!SpeechRec) {
    promptVoiceChat();
    return;
  }

  const recognition = new SpeechRec();
  const targetLocale = (typeof SPEECH_LANG_MAP !== 'undefined' && SPEECH_LANG_MAP[currentLang]) ? SPEECH_LANG_MAP[currentLang] : 'en-IN';
  recognition.lang = targetLocale;
  recognition.continuous = false;
  recognition.interimResults = false;

  if (micBtn) {
    micBtn.style.background = '#FEF2F2';
    micBtn.style.borderColor = '#DC2626';
    micBtn.innerHTML = '<span style="animation:sunGlowPulse 0.8s infinite;">🎙️</span>';
  }

  recognition.onresult = (event) => {
    const transcript = event.results[0][0].transcript;
    if (input) {
      input.value = transcript;
    }
    sendAiChatMessage(transcript);
  };

  recognition.onend = () => {
    if (micBtn) {
      micBtn.style.background = '#F0FDF4';
      micBtn.style.borderColor = '#86EFAC';
      micBtn.innerHTML = '<span style="font-size:16px;">🎤</span>';
    }
  };

  recognition.onerror = () => {
    if (micBtn) {
      micBtn.style.background = '#F0FDF4';
      micBtn.style.borderColor = '#86EFAC';
      micBtn.innerHTML = '<span style="font-size:16px;">🎤</span>';
    }
    promptVoiceChat();
  };

  try {
    recognition.start();
  } catch(e) {
    promptVoiceChat();
  }
}

