var gramhaulLiveMap = null;
var gramhaulFarmMarker = null;
var gramhaulMandiMarker = null;
var gramhaulRouteLine = null;

function initGramhaulRealMap() {
  const mapContainer = document.getElementById('gramhaul-real-osm-map');
  if (!mapContainer) return;
  if (typeof L === 'undefined' || !L.map) return;
  try {
    if (gramhaulLiveMap) { gramhaulLiveMap.remove(); gramhaulLiveMap = null; }

    const farmLat = (currentGramhaulFarmCoords && currentGramhaulFarmCoords[0]) || 17.3980;
    const farmLon = (currentGramhaulFarmCoords && currentGramhaulFarmCoords[1]) || 78.4900;
    const mandi = (typeof currentGramhaulMandi !== 'undefined' && currentGramhaulMandi) ? currentGramhaulMandi : (typeof REAL_APMC_MANDIS !== 'undefined' ? REAL_APMC_MANDIS[0] : { distKm: 7.2, coords: [17.3820, 78.4350], shortName: 'Gudimalkapur APMC' });
    const mandiCoords = mandi.coords || [17.3820, 78.4350];

    gramhaulLiveMap = L.map('gramhaul-real-osm-map', {
      center: [(farmLat + mandiCoords[0]) / 2, (farmLon + mandiCoords[1]) / 2],
      zoom: 12,
      zoomControl: false,
      attributionControl: false
    });

    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19
    }).addTo(gramhaulLiveMap);

    // 1. Live Farmer Pickup Pin (Green)
    const farmIcon = L.divIcon({
      className: 'gh-farm-pin',
      html: '<div style="background:#16A34A;color:#FFF;font-size:11px;font-weight:900;padding:5px 10px;border-radius:14px;border:2px solid #FFF;box-shadow:0 4px 14px rgba(22,163,74,0.45);white-space:nowrap;display:flex;align-items:center;gap:5px;"><span>🌾</span><span>Himayath Nagar Farm</span></div>',
      iconSize: [165, 32],
      iconAnchor: [82, 32]
    });
    gramhaulFarmMarker = L.marker([farmLat, farmLon], { icon: farmIcon }).addTo(gramhaulLiveMap);

    // 2. Plot ALL Real APMC Mandis as Interactive Pins
    if (typeof REAL_APMC_MANDIS !== 'undefined' && Array.isArray(REAL_APMC_MANDIS)) {
      REAL_APMC_MANDIS.forEach((m, idx) => {
        const isSelected = (mandi.id === m.id) || (mandi.name === m.name);
        const mandiPinIcon = L.divIcon({
          className: 'gh-all-mandi-pin',
          html: `<div style="background:${isSelected ? '#DC2626' : '#1E293B'};color:#FFF;font-size:10.5px;font-weight:900;padding:${isSelected ? '5px 10px' : '4px 8px'};border-radius:12px;border:2px solid #FFF;box-shadow:0 3px 10px rgba(0,0,0,0.3);white-space:nowrap;display:flex;align-items:center;gap:4px;cursor:pointer;transform:${isSelected ? 'scale(1.08)' : 'scale(1)'};"><span>🏛️</span><span>${m.shortName}</span></div>`,
          iconSize: [isSelected ? 160 : 130, 28],
          iconAnchor: [isSelected ? 80 : 65, 28]
        });
        const mMarker = L.marker(m.coords, { icon: mandiPinIcon }).addTo(gramhaulLiveMap);
        mMarker.on('click', () => {
          const selectEl = document.getElementById('gh-mandi-select');
          if (selectEl) selectEl.value = idx;
          updateGramhaulMandi(idx);
        });
      });
    }

    // 3. Draw Route Polyline from Farm to Selected Mandi
    gramhaulRouteLine = L.polyline([[farmLat, farmLon], mandiCoords], {
      color: '#16A34A',
      weight: 5,
      opacity: 0.9,
      dashArray: '8, 6'
    }).addTo(gramhaulLiveMap);

    // 4. Fit map bounds to show route nicely
    const group = L.featureGroup([L.marker([farmLat, farmLon]), L.marker(mandiCoords)]);
    gramhaulLiveMap.fitBounds(group.getBounds().pad(0.2));

  } catch(e) {
    console.warn('Gramhaul Map error:', e);
  }
}

var driverLiveMap = null;
var driverTruckMarker = null;
var driverPickupMarker = null;
var driverDropMarker = null;
var driverRoutePolyline = null;
var driverSimTimer = null;

function initDriverRealMap(lat, lon) {
  const mapContainer = document.getElementById('driver-real-osm-map');
  if (!mapContainer) return;
  if (typeof L === 'undefined' || !L.map) return;
  try {
    if (driverLiveMap) { driverLiveMap.remove(); driverLiveMap = null; }
    if (driverSimTimer) { clearInterval(driverSimTimer); driverSimTimer = null; }

    let activeTrip = null;
    try { activeTrip = JSON.parse(localStorage.getItem('nukrop_active_trip') || 'null'); } catch(e) {}

    // Default coordinates: Kadipikonda/Kazipet Farm -> Warangal Enamamula APMC Yard
    const pickupLat = (activeTrip && activeTrip.pickupLat) ? activeTrip.pickupLat : 17.9689;
    const pickupLon = (activeTrip && activeTrip.pickupLon) ? activeTrip.pickupLon : 79.5941;
    const dropLat   = (activeTrip && activeTrip.dropLat)   ? activeTrip.dropLat   : 17.9945;
    const dropLon   = (activeTrip && activeTrip.dropLon)   ? activeTrip.dropLon   : 79.5892;

    const currentDriverLat = lat || (pickupLat - 0.007);
    const currentDriverLon = lon || (pickupLon - 0.005);

    driverLiveMap = L.map('driver-real-osm-map', {
      center: activeTrip ? [(pickupLat + dropLat) / 2, (pickupLon + dropLon) / 2] : [currentDriverLat, currentDriverLon],
      zoom: activeTrip ? 13 : 14,
      zoomControl: false,
      attributionControl: false
    });

    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19
    }).addTo(driverLiveMap);

    const fallbackSvg = document.getElementById('driver-fallback-map');
    if (fallbackSvg) fallbackSvg.style.display = 'none';

    if (activeTrip) {
      // 1. Pickup Marker (Green Farm Pin)
      const pickupIcon = L.divIcon({
        className: 'gh-driver-pickup-pin',
        html: `<div style="background:#16A34A;color:#FFFFFF;font-size:11px;font-weight:900;padding:5px 10px;border-radius:14px;border:2px solid #FFFFFF;box-shadow:0 4px 14px rgba(22,163,74,0.45);display:flex;align-items:center;gap:5px;white-space:nowrap;">
                 <span style="font-size:13px;">🌾</span>
                 <span>${activeTrip.pickup || 'Kadipikonda Farm'}</span>
               </div>`,
        iconSize: [120, 32],
        iconAnchor: [60, 32]
      });
      driverPickupMarker = L.marker([pickupLat, pickupLon], { icon: pickupIcon }).addTo(driverLiveMap);

      // 2. Drop Marker (Red Mandi Pin)
      const dropIcon = L.divIcon({
        className: 'gh-driver-drop-pin',
        html: `<div style="background:#DC2626;color:#FFFFFF;font-size:11px;font-weight:900;padding:5px 10px;border-radius:14px;border:2px solid #FFFFFF;box-shadow:0 4px 14px rgba(220,38,38,0.45);display:flex;align-items:center;gap:5px;white-space:nowrap;">
                 <span style="font-size:13px;">🏛️</span>
                 <span>${activeTrip.mandi || 'Warangal APMC Yard'}</span>
               </div>`,
        iconSize: [130, 32],
        iconAnchor: [65, 32]
      });
      driverDropMarker = L.marker([dropLat, dropLon], { icon: dropIcon }).addTo(driverLiveMap);

      // 3. Driver Truck Marker
      const truckIcon = L.divIcon({
        className: 'gh-driver-truck-pin',
        html: `<div style="position:relative;display:flex;flex-direction:column;align-items:center;">
                 <div style="background:#0F172A;color:#C6FF00;font-size:9.5px;font-weight:900;padding:2px 6px;border-radius:6px;box-shadow:0 2px 6px rgba(0,0,0,0.3);white-space:nowrap;margin-bottom:3px;border:1px solid rgba(198,255,0,0.5);">
                   TS 03 UB 4491
                 </div>
                 <div style="width:38px;height:38px;border-radius:50%;background:#C6FF00;border:3px solid #0F172A;display:flex;align-items:center;justify-content:center;box-shadow:0 4px 14px rgba(0,0,0,0.35);">
                   <svg width="20" height="20" viewBox="0 0 24 24" fill="#0F172A">
                     <path d="M18 18.5a1.5 1.5 0 0 1-1.5-1.5 1.5 1.5 0 0 1 1.5-1.5 1.5 1.5 0 0 1 1.5 1.5 1.5 1.5 0 0 1-1.5 1.5m1.5-9H17V12h4.5M6 18.5A1.5 1.5 0 0 1 4.5 17 1.5 1.5 0 0 1 6 15.5 1.5 1.5 0 0 1 7.5 17 1.5 1.5 0 0 1 6 18.5M20 7h-3V3H3a2 2 0 0 0-2 2v11a2 2 0 0 0 2 2h.2a3 3 0 0 0 5.6 0h6.4a3 3 0 0 0 5.6 0h1.2a2 2 0 0 0 2-2v-5l-3-4z"/>
                   </svg>
                 </div>
               </div>`,
        iconSize: [90, 60],
        iconAnchor: [45, 50]
      });
      driverTruckMarker = L.marker([currentDriverLat, currentDriverLon], { icon: truckIcon }).addTo(driverLiveMap);

      // 4. Multi-point Road Polyline from Driver -> Pickup -> Drop Mandi
      const intermediatePoints = [
        [currentDriverLat, currentDriverLon],
        [currentDriverLat + (pickupLat - currentDriverLat) * 0.5, currentDriverLon + (pickupLon - currentDriverLon) * 0.5 + 0.0015],
        [pickupLat, pickupLon],
        [pickupLat + 0.008, pickupLon - 0.003],
        [pickupLat + 0.018, pickupLon - 0.004],
        [dropLat, dropLon]
      ];

      driverRoutePolyline = L.polyline(intermediatePoints, {
        color: '#16A34A',
        weight: 5,
        opacity: 0.9,
        lineCap: 'round',
        lineJoin: 'round',
        dashArray: '10, 8'
      }).addTo(driverLiveMap);

      // Fit bounds so entire route is clearly visible
      driverLiveMap.fitBounds([
        [Math.min(currentDriverLat, pickupLat, dropLat) - 0.003, Math.min(currentDriverLon, pickupLon, dropLon) - 0.003],
        [Math.max(currentDriverLat, pickupLat, dropLat) + 0.003, Math.max(currentDriverLon, pickupLon, dropLon) + 0.003]
      ], { padding: [50, 50] });

      // Real GPS coordinates maintained without jitter loop
      if (driverSimTimer) { clearInterval(driverSimTimer); driverSimTimer = null; }
    } else {
      // Standby Driver Marker
      const standbyIcon = L.divIcon({
        className: 'gh-driver-standby-pin',
        html: `<div style="position:relative;display:flex;flex-direction:column;align-items:center;">
                 <div style="background:#0F172A;color:#C6FF00;font-size:9.5px;font-weight:900;padding:2px 6px;border-radius:6px;box-shadow:0 2px 6px rgba(0,0,0,0.3);white-space:nowrap;margin-bottom:3px;">
                   TS 03 UB 4491 · Online
                 </div>
                 <div style="width:38px;height:38px;border-radius:50%;background:#C6FF00;border:3px solid #0F172A;display:flex;align-items:center;justify-content:center;box-shadow:0 4px 14px rgba(0,0,0,0.35);">
                   <svg width="20" height="20" viewBox="0 0 24 24" fill="#0F172A">
                     <path d="M18 18.5a1.5 1.5 0 0 1-1.5-1.5 1.5 1.5 0 0 1 1.5-1.5 1.5 1.5 0 0 1 1.5 1.5 1.5 1.5 0 0 1-1.5 1.5m1.5-9H17V12h4.5M6 18.5A1.5 1.5 0 0 1 4.5 17 1.5 1.5 0 0 1 6 15.5 1.5 1.5 0 0 1 7.5 17 1.5 1.5 0 0 1 6 18.5M20 7h-3V3H3a2 2 0 0 0-2 2v11a2 2 0 0 0 2 2h.2a3 3 0 0 0 5.6 0h6.4a3 3 0 0 0 5.6 0h1.2a2 2 0 0 0 2-2v-5l-3-4z"/>
                   </svg>
                 </div>
               </div>`,
        iconSize: [80, 56],
        iconAnchor: [40, 48]
      });
      driverTruckMarker = L.marker([currentDriverLat, currentDriverLon], { icon: standbyIcon }).addTo(driverLiveMap);
    }

    setTimeout(() => { if (driverLiveMap) driverLiveMap.invalidateSize(); }, 200);
  } catch(e) {
    console.warn('Driver Leaflet Map init fallback:', e);
  }
}

function startDriverRealMovementSimulation(points) {
  if (driverSimTimer) clearInterval(driverSimTimer);
  if (!points || points.length < 2) return;
  let currIdx = 0;
  let fraction = 0;
  driverSimTimer = setInterval(() => {
    fraction += 0.05;
    if (fraction >= 1) {
      fraction = 0;
      currIdx = (currIdx + 1) % (points.length - 1);
    }
    const p1 = points[currIdx];
    const p2 = points[currIdx + 1];
    const curLat = p1[0] + (p2[0] - p1[0]) * fraction;
    const curLon = p1[1] + (p2[1] - p1[1]) * fraction;

    if (driverTruckMarker && typeof driverTruckMarker.setLatLng === 'function') {
      driverTruckMarker.setLatLng([curLat, curLon]);
    }
    driverLiveCoords = [curLat, curLon];
    localStorage.setItem('gh_driver_last_lat', String(curLat));
    localStorage.setItem('gh_driver_last_lon', String(curLon));

    if (typeof gramhaulTruckMarker !== 'undefined' && gramhaulTruckMarker && typeof gramhaulTruckMarker.setLatLng === 'function') {
      gramhaulTruckMarker.setLatLng([curLat, curLon]);
    }
  }, 1200);
}

