        <input type="text" placeholder="${searchPlaceholder}" oninput="filterMachinerySearch(this.value)" style="width:100%;padding:10px 14px;border:1.5px solid #CBD5E1;border-radius:14px;font-size:12.5px;font-weight:600;outline:none;background:#FFFFFF;color:#0F172A;box-sizing:border-box;box-shadow:0 1px 4px rgba(0,0,0,0.03);">
      </div>

