function confirmUserLogout() {
  const modal = document.getElementById('nukrop-logout-confirm-modal');
  if (modal) modal.remove();

  const settingsModal = document.getElementById('app-settings-modal');
  if (settingsModal) settingsModal.remove();

  try {
    localStorage.removeItem('nukrop_active_session');
    localStorage.removeItem('nukrop_user_token');
    localStorage.removeItem('gh_driver_online');
    localStorage.removeItem('nukrop_user_email');
    localStorage.removeItem('nukrop_auth_method');
  } catch(e) {}

  if (typeof showLuxuryToast === 'function') {
    showLuxuryToast('👋 Successfully logged out. Welcome back anytime!', 'info');
  }

  setTimeout(() => {
    plantixFlowState.currentScreen = 'login';
    let overlay = document.getElementById('startup-experience-overlay');
    if (!overlay) {
      const chassis = document.querySelector('.phone-chassis');
      if (chassis) {
        chassis.insertAdjacentHTML('beforeend', '<div id="startup-experience-overlay" style="position:absolute;inset:0;background:#FFFFFF;border-radius:48px;overflow:hidden;z-index:99999;display:flex;flex-direction:column;"></div>');
        overlay = document.getElementById('startup-experience-overlay');
      }
    }
    if (overlay) {
      overlay.style.display = 'flex';
      overlay.style.pointerEvents = 'auto';
      overlay.style.opacity = '1';
      overlay.style.transform = 'scale(1)';
      renderPlantixFlow();
    }
  }, 300);
}

