let activeParcelIndex = 0;
let agristackMapInstance = null;
let gramhaulMapInstance = null;

function initAgristackOpenStreetMap() {
  const mapContainer = document.getElementById('agristack-osm-map');
  if (!mapContainer) return;

  const parcel = AGRISTACK_FARMER_PROFILE.parcels[activeParcelIndex] || AGRISTACK_FARMER_PROFILE.parcels[0];
  const centerLat = Array.isArray(parcel.coordinates) ? parcel.coordinates[0] : 17.9689;
  const centerLng = Array.isArray(parcel.coordinates) ? parcel.coordinates[1] : 79.5941;

  if (typeof L !== 'undefined' && L.map) {
    try {
      if (agristackMapInstance) {
        agristackMapInstance.remove();
        agristackMapInstance = null;
      }

      agristackMapInstance = L.map('agristack-osm-map', {
        center: [centerLat, centerLng],
        zoom: 16,
        zoomControl: true,
        attributionControl: false
      });

      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        maxZoom: 19
      }).addTo(agristackMapInstance);

      // Add Cadastral Polygons for all parcels
      AGRISTACK_FARMER_PROFILE.parcels.forEach((p, idx) => {
        if (p.polygonBounds) {
          const isCurrent = idx === activeParcelIndex;
          const poly = L.polygon(p.polygonBounds, {
            color: isCurrent ? '#16A34A' : '#64748B',
            fillColor: isCurrent ? '#22C55E' : '#94A3B8',
            fillOpacity: isCurrent ? 0.45 : 0.2,
            weight: isCurrent ? 3 : 1.5
          }).addTo(agristackMapInstance);

          poly.bindPopup(`
            <div style="font-size:11px;font-weight:900;color:#1B5E20;">Survey No. ${p.surveyNumber}</div>
            <div style="font-size:10px;color:#334155;">Extent: ${p.extentAcres} Acres · ${p.khataNumber}</div>
            <div style="font-size:9px;color:#15803D;">${p.ownershipType}</div>
          `);

          if (isCurrent) {
            poly.openPopup();
          }
        }
      });

      // Add Farm Center Marker
      L.marker([centerLat, centerLng]).addTo(agristackMapInstance)
        .bindPopup(`<b>🏡 ${parcel.pattadarName}</b><br/>Survey ${parcel.surveyNumber} (${parcel.extentAcres} Ac)`);
    } catch(err) {
      console.warn('Leaflet AgriStack init fallback:', err);
    }
  }
}

function initGramhaulOpenStreetMap() {
  const mapContainer = document.getElementById('gramhaul-osm-map');
  if (!mapContainer) return;

  const farmCoords = [17.9689, 79.5941];
  const mandiEnumamulaCoords = [17.9942, 79.6234];
  const mandiHydCoords = [17.4720, 78.4730];

  if (typeof L !== 'undefined' && L.map) {
    try {
      if (gramhaulMapInstance) {
        gramhaulMapInstance.remove();
        gramhaulMapInstance = null;
      }

      gramhaulMapInstance = L.map('gramhaul-osm-map', {
        center: [17.9780, 79.6050],
        zoom: 13,
        zoomControl: true,
        attributionControl: false
      });

      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        maxZoom: 19
      }).addTo(gramhaulMapInstance);

      // Farm Marker
      const farmMarker = L.marker(farmCoords).addTo(gramhaulMapInstance)
        .bindPopup('<b>🏡 Your Farm</b><br/>Survey 142/A · Warangal Rural');

      // Mandi Markers
      L.marker(mandiEnumamulaCoords).addTo(gramhaulMapInstance)
        .bindPopup('<b>🏢 Warangal Enumamula APMC</b><br/>Major APMC Yard · 4.8 km');

      // Route Polyline to APMC
      L.polyline([farmCoords, [17.9820, 79.6080], mandiEnumamulaCoords], {
        color: '#16A34A',
        weight: 4,
        dashArray: '6, 6'
      }).addTo(gramhaulMapInstance);

      // Add Pooled Trucks Markers
      const truckCoords = [
        [17.9750, 79.5990],
        [17.9880, 79.6150],
        [17.9620, 79.6050]
      ];

      GRAMHAUL_POOLED_TRUCKS.forEach((t, idx) => {
        const coord = truckCoords[idx % truckCoords.length];
        const truckMarker = L.marker(coord).addTo(gramhaulMapInstance);
        truckMarker.bindPopup(`
          <div style="font-size:11px;font-weight:900;color:#0F172A;">🚚 ${t.vehicle} (${t.plate})</div>
          <div style="font-size:10px;color:#15803D;font-weight:800;">₹${t.ratePerBag}/Bag · ${t.freeSlots} Slots Free</div>
          <div style="font-size:9.5px;color:#64748B;">Departs: ${t.departure}</div>
          <button onclick="openGramhaulBookingModal(${idx})" style="background:#1B5E20;color:#FFFFFF;border:none;border-radius:6px;padding:3px 8px;font-size:9px;font-weight:800;margin-top:4px;cursor:pointer;">Book Slot</button>
        `);
      });
    } catch(err) {
      console.warn('Leaflet GramHaul init fallback:', err);
    }
  }
}

function switchAgristackParcel(idx) {
  activeParcelIndex = idx;
  const container = document.getElementById('agristack-content-view');
  if (container) {
    container.innerHTML = getAgristackDynamicBodyHtml();
    setTimeout(initAgristackOpenStreetMap, 60);
  }
}

