function submitAgriStackObjection(surveyNo) {
  const isTe = currentLang === 'te';
  const reason = document.getElementById('obj-reason-select')?.value || 'crop_mismatch';
  const grievanceId = 'GR-AGRI-' + Math.floor(10000 + Math.random() * 90000);

  closeAgriStackObjectionModal();

  showPushNotificationToast({
    title: TL(`⚠️ AgriStack Objection Filed (#${grievanceId})`, `⚠️ అభ్యంతరం నమోదు చేయబడింది (#${grievanceId})`, `⚠️ AgriStack Objection Filed (#${grievanceId})`),
    msg: TL(`Objection for Survey No. ${surveyNo} successfully submitted to District Agricultural Officer & Tehsildar for field re-verification.`, `సర్వే నం. ${surveyNo} పై మీ అభ్యంతరం జిల్లా వ్యవసాయ అధికారి (DAO) మరియు తహశీల్దార్‌కు పరిశీలన కోసం పంపబడింది.`, `Objection for Survey No. ${surveyNo} successfully submitted to District Agricultural Officer & Tehsildar for field re-verification.`),
    type: 'alert_created'
  });

  alert(TL(`✅ AgriStack Crop Survey Objection Registered!\n\nGrievance ID: #${grievanceId}\nSurvey Number: ${surveyNo}\nRouted to: District Agricultural Officer (DAO) & Tehsildar\n\nField officer inspection scheduled within 48 hours.`, `✅ డిజిటల్ క్రాప్ సర్వే అభ్యంతరం విజయవంతంగా నమోదైంది!\n\nGrievance ID: #${grievanceId}\nసర్వే నం: ${surveyNo}\nఅధికారి: జిల్లా వ్యవసాయ అధికారి (DAO) & ఎమ్మార్వో\n\n48 గంటల్లో రెవెన్యూ అధికారి క్షేత్రస్థాయి విచారణ చేపడతారు.`, `✅ AgriStack Crop Survey Objection Registered!\n\nGrievance ID: #${grievanceId}\nSurvey Number: ${surveyNo}\nRouted to: District Agricultural Officer (DAO) & Tehsildar\n\nField officer inspection scheduled within 48 hours.`));
}

