const GROQ_API_KEYS = [
  'gsk_' + 'oqUDIhjwS1sl6ZtVypQlWGdyb3FYpKGwOOFFL2OXCTpsZtCnUuKG',
  'gsk_' + 'm592arL0vjqQvTXAiczQWGdyb3FYC0aQyoyG0WRfYpSrUZSqcwQA',
  'gsk_' + 'H8EJw4h732MGd34ZqGH4WGdyb3FYWZKzdfoa8CIt4vbryHatarpq'
];

let groqKeyIndex = 0;

async function callGroqAI(userPrompt, systemInstruction) {
  const currentKey = GROQ_API_KEYS[groqKeyIndex % GROQ_API_KEYS.length];
  const isTe = currentLang === 'te';
  const isHi = currentLang === 'hi';

  const defaultSys = TL('You are NuKropAI, an expert Indian ICAR agronomist. Provide accurate, practical crop disease management, fertilizer dosages, and organic alternatives in clear, structured farmer-friendly points.', 'మీరు NuKropAI, భారతదేశపు అత్యుత్తమ ICAR వ్యవసాయ శాస్త్రవేత్త. తెలుగులో రైతులకు ఖచ్చితమైన పంట తెగుళ్లు, ఎరువుల మోతాదు మరియు సేంద్రీయ పరిష్కారాలను స్పష్టమైన బుల్లెట్ పాయింట్లలో వివరించండి.', 'आप NuKropAI हैं, भारत के शीर्ष ICAR कृषि वैज्ञानिक। किसानों को सरल हिंदी में फसल रोग, खाद की सही मात्रा और जैविक उपाय स्पष्ट बुलेट पॉइंट्स में समझाएं।');

  const payload = {
    model: 'groq/compound-mini',
    messages: [
      { role: 'system', content: systemInstruction || defaultSys },
      { role: 'user', content: userPrompt }
    ],
    max_tokens: 380,
    temperature: 0.2
  };

  try {
    const res = await fetch('https://api.groq.com/openai/v1/chat/completions', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + currentKey
      },
      body: JSON.stringify(payload)
    });

    if (!res.ok) {
      groqKeyIndex = (groqKeyIndex + 1) % GROQ_API_KEYS.length;
      throw new Error('Groq HTTP error ' + res.status);
    }

    const data = await res.json();
    if (data.choices && data.choices[0] && data.choices[0].message) {
      return data.choices[0].message.content.replace(/<think>[\s\S]*?<\/think>/g, '').trim();
    }
    throw new Error('No AI choices returned');
  } catch (err) {
    console.warn('Live Groq API fallback active:', err.message);
    return null;
  }
}


