let activeScannerTab = 'camera';

function switchScannerTab(tab) {
  activeScannerTab = tab;
  const camView = document.getElementById('scanner-camera-view');
  const histView = document.getElementById('scanner-history-view');
  const tabCamBtn = document.getElementById('scan-tab-camera-btn');
  const tabHistBtn = document.getElementById('scan-tab-history-btn');

  if (tab === 'camera') {
    if (camView) camView.style.display = 'block';
    if (histView) histView.style.display = 'none';
    if (tabCamBtn) {
      tabCamBtn.style.background = '#1B5E20';
      tabCamBtn.style.color = '#FFFFFF';
    }
    if (tabHistBtn) {
      tabHistBtn.style.background = '#FFFFFF';
      tabHistBtn.style.color = '#15803D';
    }
  } else {
    if (camView) camView.style.display = 'none';
    if (histView) {
      histView.style.display = 'block';
      renderSavedScansHistoryDOM();
    }
    if (tabCamBtn) {
      tabCamBtn.style.background = '#FFFFFF';
      tabCamBtn.style.color = '#15803D';
    }
    if (tabHistBtn) {
      tabHistBtn.style.background = '#1B5E20';
      tabHistBtn.style.color = '#FFFFFF';
    }
  }
}

