function deleteSavedScan(id) {
  const isTe = currentLang === 'te';
  if (confirm(TL('Delete this saved scan record?', 'ఈ స్కాన్ వివరాలను తొలగించాలా?', 'Delete this saved scan record?'))) {
    savedScansHistory = savedScansHistory.filter(s => s.id !== id);
    persistScansToStorage();
    renderSavedScansHistoryDOM();
  }
}

