/* ═════════════════ HARDWARE CAMERA & LIVE STREAM CONTROLLER ═════════════════ */
let liveCameraStream = null;

window.onNativeCameraPermissionGranted = function() {
  console.log("[NativeBridge] Camera permission granted by user");
  startLiveCameraStream();
};

async function startLiveCameraStream() {
  const video = document.getElementById('vf-live-video');
  const hudStatus = document.getElementById('scanner-hud-status');
  const targetText = document.getElementById('scan-target-text');
  const guidanceText = document.getElementById('scan-guidance-text');
  const scanBtn = document.getElementById('run-scan-btn');

  if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: {
          facingMode: { ideal: 'environment' },
          width: { ideal: 1280 },
          height: { ideal: 720 }
        }
      });
      liveCameraStream = stream;
      if (video) {
        video.srcObject = stream;
        video.style.display = 'block';
        await video.play();
      }
      if (hudStatus) hudStatus.innerHTML = '<span style="color:#22C55E;">●</span> ' + TL('Live Camera Active', 'లైవ్ కెమెరా ఆన్‌లో ఉంది', 'लाइव कैमरा सक्रिय');
      if (targetText) targetText.style.display = 'none';
      if (guidanceText) guidanceText.textContent = TL('Point at affected crop leaf & tap Snap below', 'వ్యాధి సోకిన ఆకుపై కెమెరా ఉంచి స్నాప్ నొక్కండి', 'रोगग्रस्त पत्ती पर कैमरा रख स्नैप दबाएं');
      if (scanBtn) {
        scanBtn.innerHTML = TL('📸 Snap Photo & Diagnose', '📸 ఫోటో తీసి విశ్లేషించండి', '📸 फोटो लें और निदान करें');
      }
      return true;
    } catch (err) {
      console.warn('getUserMedia stream error, falling back to native capture:', err);
    }
  }
  return false;
}

function stopLiveCameraStream() {
  if (liveCameraStream) {
    liveCameraStream.getTracks().forEach(t => t.stop());
    liveCameraStream = null;
  }
  const video = document.getElementById('vf-live-video');
  if (video) {
    video.srcObject = null;
    video.style.display = 'none';
  }
}

function captureFrameFromLiveCamera() {
  const video = document.getElementById('vf-live-video');
  const canvas = document.getElementById('vf-capture-canvas');
  if (video && video.videoWidth > 0 && canvas) {
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    const dataUrl = canvas.toDataURL('image/jpeg', 0.88);
    uploadedScanImageData = dataUrl;

    // Freeze snapshot in viewfinder
    const vfFrame = document.querySelector('.viewfinder-frame');
    if (vfFrame) {
      const prev = vfFrame.querySelector('.vf-real-preview');
      if (prev) prev.remove();
      const img = document.createElement('img');
      img.className = 'vf-real-preview';
      img.src = dataUrl;
      img.style.position = 'absolute';
      img.style.inset = '0';
      img.style.width = '100%';
      img.style.height = '100%';
      img.style.objectFit = 'cover';
      img.style.borderRadius = '18px';
      img.style.zIndex = '5';
      vfFrame.appendChild(img);
    }
    stopLiveCameraStream();
    return true;
  }
  return false;
}

function triggerDeviceCameraCapture() {
  // First try starting live camera stream in viewfinder
  startLiveCameraStream().then(started => {
    if (!started) {
      // Direct invoke native Android Camera hardware via file input with capture="environment"
      const camInp = document.getElementById('real-camera-capture-input');
      if (camInp) camInp.click();
    }
  });
}

function handleViewfinderClick() {
  if (liveCameraStream) {
    captureFrameFromLiveCamera();
    startScannerDiagnostic();
  } else {
    triggerDeviceCameraCapture();
  }
}

// Hook startScannerDiagnostic to snap from live stream if active
