function selectCropTab(idx) {
  activeCropIdx = idx;
  openScreen('home', document.getElementById('tab-home'));
}

function renderCropModalList(cropList) {
  const grid = document.getElementById('crop-modal-grid');
  if (!grid) return;
  if (!cropList || cropList.length === 0) {
    grid.innerHTML = `<div style="grid-column: span 3; text-align:center; padding:30px 0; color:#64748B; font-size:13px; font-weight:700;">${currentLang==='te'?'పంట దొరకలేదు':(currentLang==='hi'?'कोई फसल नहीं मिली':'No matching crop found')}</div>`;
    return;
  }
  grid.innerHTML = cropList.map(c => `
    <div onclick="addCropToSelection('${c.id}')" style="display:flex;flex-direction:column;align-items:center;cursor:pointer;">
      <div class="plantix-crop-badge">
        ${getCropIconImg(c.path, c.id)}
      </div>
      <span style="font-size:10px;font-weight:700;color:#1E293B;text-align:center;line-height:1.2;margin-top:2px;">${getLocalizedCropName(c.id)}</span>
    </div>
  `).join('');
}

function filterCropCatalog(query) {
  const q = (query || '').toLowerCase().trim();
  if (!q) {
    renderCropModalList(OPENFARM_CROPS_CATALOG);
  } else {
    const filtered = OPENFARM_CROPS_CATALOG.filter(c => {
      const locName = getLocalizedCropName(c.id).toLowerCase();
      const engName = (CROP_TRANSLATIONS[c.id]?.en || c.id).toLowerCase();
      return locName.includes(q) || engName.includes(q) || c.id.includes(q);
    });
    renderCropModalList(filtered);
  }
}

function openCropModal() {
  cropModalMode = 'home';
  const modal = document.getElementById('crop-modal');
  const title = document.getElementById('m-crop-title');
  const sub = document.getElementById('m-crop-sub');
  const searchInput = document.getElementById('crop-search-input');
  
  const t = I18N[currentLang] || I18N.te;
  if (title) title.textContent = t.modalTitle;
  if (sub) sub.textContent = t.modalSub;
  if (searchInput) searchInput.value = '';

  renderCropModalList(OPENFARM_CROPS_CATALOG);
  if (modal) modal.style.display = 'flex';
}

function closeCropModal(e) {
  const modal = document.getElementById('crop-modal');
  if (modal) modal.style.display = 'none';
}

function addCropToSelection(cropId) {
  const item = OPENFARM_CROPS_CATALOG.find(x => x.id === cropId);
  if (!item) return;

  if (cropModalMode === 'mandi') {
    const locName = getLocalizedCropName(cropId);
    mandiSearchCrop = locName;
    mandiSelectedPopular = cropId;
    closeCropModal();
    const cropEl = document.getElementById('mandi-crop-inp');
    if (cropEl) cropEl.value = locName;
    executeMandiSearch();
    return;
  }

  const existingIdx = myActiveCrops.findIndex(x => x.id === cropId);
  if (existingIdx !== -1) {
    activeCropIdx = existingIdx;
  } else {
    myActiveCrops.push(item);
    activeCropIdx = myActiveCrops.length - 1;
  }

  closeCropModal();
  openScreen('home', document.getElementById('tab-home'));
}

function addNewKhataEntry() {
  openKhataEntryModal();
}


