function updateStatusBarTheme(screenKey) {
  const bar = document.querySelector('.system-status-bar');
  if (!bar) return;

  if (bar.style) {
    bar.style.background = '#F8FAF8';
    bar.style.color = '#0F172A';
    bar.style.borderBottom = 'none';
  }
  const svgs = bar.querySelectorAll ? bar.querySelectorAll('svg') : [];
  if (svgs && svgs.forEach) {
    svgs.forEach(s => {
      if (s.getAttribute && s.getAttribute('stroke')) s.setAttribute('stroke', '#0F172A');
      if (s.getAttribute && s.getAttribute('fill') && s.getAttribute('fill') !== 'none') s.setAttribute('fill', '#0F172A');
    });
  }
}


