function openScreen(screenKey, tabElement) {
  currentScreenKey = screenKey || 'home';
  currentTabElement = tabElement || null;

  if (['home', 'community', 'scanner', 'scan', 'market', 'profile'].includes(currentScreenKey)) {
    localStorage.setItem('nukrop_user_role', 'farmer');
    authUserRole = 'farmer';
  }

  document.querySelectorAll('.dock-tab-btn').forEach(b => b.classList.remove('active'));
  // Update currentAppScreen for realtime subscription tracking
  window.currentAppScreen = screenKey;
  if (tabElement) {
    tabElement.classList.add('active');
  } else {
    const tabMap = {
      home:'tab-home', community:'tab-community', market:'tab-market', profile:'tab-profile',
      driver_dashboard:'tab-driver-cockpit', gramhaul:'tab-driver-loads',
      khata:'tab-driver-earnings'
    };
    if (tabMap[screenKey]) {
      const el = document.getElementById(tabMap[screenKey]);
      if (el) el.classList.add('active');
    }
  }

  // Prevent UI collision: Hide global bottom dock on driver dashboard since it has its own
  const dockWrap = document.querySelector('.bottom-dock-wrap');
  const screenContainer = document.getElementById('screen-container');
  const container = document.getElementById('screen-body');

  if (screenKey === 'driver_dashboard') {
    if (dockWrap) dockWrap.style.display = 'none';
    if (screenContainer) {
      screenContainer.style.overflow = 'hidden';
      screenContainer.style.paddingBottom = '0px';
    }
    if (container) {
      container.style.height = '100%';
      container.style.display = 'flex';
      container.style.flexDirection = 'column';
    }
  } else {
    if (dockWrap) dockWrap.style.display = 'block';
    if (screenContainer) {
      screenContainer.style.overflow = '';
      screenContainer.style.paddingBottom = '';
    }
    if (container) {
      container.style.height = '';
      container.style.display = '';
      container.style.flexDirection = '';
    }
  }

  if (container) {
    container.classList.remove('screen-fade');
    void container.offsetWidth;
    container.classList.add('screen-fade');
    const viewFn = APP_VIEWS[screenKey] || APP_VIEWS.home;
    container.innerHTML = viewFn();
    setTimeout(applyCustomCropDropdowns, 0);
  }

  if (screenContainer) screenContainer.scrollTop = 0;

  if (screenKey === 'home') updateWeatherCardDom();
  updateStatusBarTheme(screenKey);
  if (screenKey === 'calc_fert') calcFertilizerDose();
  if (screenKey === 'calc_pest') calcPesticideDose();
  if (screenKey === 'scan' || screenKey === 'scanner') {
    if (window.AndroidBridge && typeof AndroidBridge.requestCameraPermission === 'function') {
      AndroidBridge.requestCameraPermission();
    }
    setTimeout(startLiveCameraStream, 120);
  } else {
    stopLiveCameraStream();
  }
  if (screenKey === 'calc_budget') calcBudgetRoi();
  updateBottomDockForRole();
}

function syncSideNav(buttonId) {
  document.querySelectorAll('#side-nav-group .panel-nav-btn').forEach(b => b.classList.remove('active'));
  const btn = document.getElementById(buttonId);
  if (btn) btn.classList.add('active');
}

