function onBudgetCropChange() {
  const crop = document.getElementById('budget-crop-select')?.value || 'cotton';
  const d = BUDGET_CROP_DEFAULTS[crop] || BUDGET_CROP_DEFAULTS.cotton;
  const set = (id, val) => { const el = document.getElementById(id); if (el) el.value = val; };
  set('b-yield', d.yield);
  set('b-price', d.price);
  set('b-cost', d.cost);
  set('b-seed', d.seed);
  set('b-fert', d.fert);
  set('b-labor', d.labor);
  set('b-irrig', d.irrig);
  calcBudgetRoi();
}

function onBudgetSeasonChange(season) {
  // Season-specific adjustments
  const multipliers = { kharif: 1.0, rabi: 0.9, zaid: 1.1 };
  const m = multipliers[season] || 1.0;
  const priceEl = document.getElementById('b-price');
  if (priceEl) {
    const base = parseFloat(priceEl.value) || 7480;
    priceEl.value = Math.round(base * m);
  }
  calcBudgetRoi();
}


// ── BUDGET ROI CALCULATOR LOGIC (v3.0) ──






function calcBudgetRoi() {
  const acres = parseFloat(document.getElementById('b-acres')?.value) || 4.5;
  const yld = parseFloat(document.getElementById('b-yield')?.value) || 8;
  const price = parseFloat(document.getElementById('b-price')?.value) || 7480;
  const seed = parseFloat(document.getElementById('b-seed')?.value) || 0;
  const fert = parseFloat(document.getElementById('b-fert')?.value) || 0;
  const labor = parseFloat(document.getElementById('b-labor')?.value) || 0;
  const irrig = parseFloat(document.getElementById('b-irrig')?.value) || 0;
  const totalCost = (seed + fert + labor + irrig) || parseFloat(document.getElementById('b-cost')?.value) || 45000;

  const costEl = document.getElementById('b-cost');
  if (costEl && (seed + fert + labor + irrig) > 0) costEl.value = seed + fert + labor + irrig;

  const out = document.getElementById('budget-result-view');
  if (!out) return;

  const gross = yld * acres * price;
  const net = gross - totalCost;
  const roi = ((net / totalCost) * 100).toFixed(1);
  const breakEven = Math.ceil(totalCost / (yld * acres));
  const payback3m = Math.ceil(totalCost / 3);
  const isProfit = net >= 0;

  out.innerHTML = `
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;border-bottom:1px solid #BBF7D0;padding-bottom:10px;">
      <div>
        <span style="font-size:10px;font-weight:900;color:#15803D;background:#DCFCE7;padding:2px 6px;border-radius:6px;">PROFIT & LOSS</span>
        <div style="font-size:15px;font-weight:900;color:#0F172A;margin-top:2px;">${acres} Acres · ${yld} Qtl/Acre</div>
      </div>
      <button onclick="speakAiSpeech(this.closest('#budget-result-view').innerText, this)" style="background:#F0FDF4;border:1px solid #86EFAC;color:#15803D;font-size:11px;font-weight:800;border-radius:12px;padding:5px 10px;cursor:pointer;">
        🔊 ${TL('Listen', 'వినండి', 'सुनें')}
      </button>
    </div>

    <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:14px;text-align:center;">
      <div style="background:#FFFFFF;border:1.2px solid #BBF7D0;border-radius:14px;padding:10px;">
        <div style="font-size:10px;font-weight:800;color:#64748B;">GROSS REVENUE</div>
        <div style="font-size:18px;font-weight:900;color:#0B4628;margin:2px 0;">₹${gross.toLocaleString('en-IN')}</div>
      </div>
      <div style="background:#FFFFFF;border:1.2px solid #FCA5A5;border-radius:14px;padding:10px;">
        <div style="font-size:10px;font-weight:800;color:#64748B;">TOTAL COST</div>
        <div style="font-size:18px;font-weight:900;color:#DC2626;margin:2px 0;">₹${totalCost.toLocaleString('en-IN')}</div>
      </div>
      <div style="background:${isProfit ? '#F0FDF4' : '#FFF1F2'};border:2px solid ${isProfit ? '#86EFAC' : '#FCA5A5'};border-radius:14px;padding:12px;grid-column:span 2;">
        <div style="font-size:10px;font-weight:800;color:#64748B;">NET PROFIT</div>
        <div style="font-size:28px;font-weight:900;color:${isProfit ? '#15803D' : '#DC2626'};margin:2px 0;">${isProfit ? '+' : ''}₹${net.toLocaleString('en-IN')}</div>
        <div style="font-size:12px;font-weight:900;color:${isProfit ? '#15803D' : '#DC2626'};">ROI: ${roi}% ${isProfit ? '✅ Profitable' : '⚠️ At Loss'}</div>
      </div>
    </div>

    <div style="background:#FFFFFF;border:1px solid #E2ECE2;border-radius:14px;padding:12px 14px;margin-bottom:14px;">
      <div style="font-size:12px;font-weight:900;color:#0F172A;margin-bottom:8px;">📉 ${TL('Key Metrics', 'ముఖ్యమైన సంఖ్యలు', 'प्रमुख आंकड़े')}:</div>
      <div style="display:flex;flex-direction:column;gap:6px;font-size:11.5px;color:#334155;">
        <div style="display:flex;justify-content:space-between;"><span>📉 Break-Even Price:</span><span style="font-weight:800;">₹${breakEven.toLocaleString('en-IN')}/Qtl</span></div>
        <div style="display:flex;justify-content:space-between;"><span>📅 Monthly Repayment (3M):</span><span style="font-weight:800;">₹${payback3m.toLocaleString('en-IN')}/mo</span></div>
        <div style="display:flex;justify-content:space-between;"><span>📦 Total Harvest:</span><span style="font-weight:800;">${(yld * acres).toFixed(1)} Quintals</span></div>
        <div style="display:flex;justify-content:space-between;"><span>💰 Per Acre Profit:</span><span style="font-weight:800;color:${isProfit ? '#15803D' : '#DC2626'};">₹${Math.round(net / acres).toLocaleString('en-IN')}</span></div>
      </div>
    </div>

    <div style="display:flex;justify-content:space-between;align-items:center;background:#EFF6FF;border:1px solid #BFDBFE;border-radius:12px;padding:10px 14px;">
      <div>
        <div style="font-size:10px;font-weight:800;color:#1D4ED8;">KCC LOAN ELIGIBLE</div>
        <div style="font-size:16px;font-weight:900;color:#1D4ED8;">₹${Math.round(totalCost * 1.25).toLocaleString('en-IN')}</div>
      </div>
      <button onclick="openScreen('loan',null);syncSideNav('btn-loan')" style="background:#1D4ED8;color:#FFFFFF;border:none;border-radius:12px;padding:8px 14px;font-size:12px;font-weight:800;cursor:pointer;">Apply KCC →</button>
    </div>
  `;
}



function syncBudgetCost() {
  const seed = parseFloat(document.getElementById('b-seed')?.value) || 0;
  const fert = parseFloat(document.getElementById('b-fert')?.value) || 0;
  const labor = parseFloat(document.getElementById('b-labor')?.value) || 0;
  const irrig = parseFloat(document.getElementById('b-irrig')?.value) || 0;
  const total = seed + fert + labor + irrig;
  const costEl = document.getElementById('b-cost');
  if (costEl && total > 0) costEl.value = total;
  calcBudgetRoi();
}


async function sendChatMsg() {
  const input = document.getElementById('ai-chat-input');
  if (!input) return;
  const txt = input.value.trim();
  if (!txt) return;
  const box = document.getElementById('chat-stream-box');
  if (!box) return;

  const userMsgId = 'msg-user-' + Date.now();
  const aiMsgId = 'msg-ai-' + Date.now();

  box.innerHTML += `<div id="${userMsgId}" style="background:#0D6EFD;color:#FFFFFF;border-radius:14px;padding:12px;font-size:12px;margin-bottom:8px;align-self:flex-end;">${txt}</div>`;
  input.value = '';
  box.scrollTop = box.scrollHeight;

  const isTe = currentLang === 'te';
  const isHi = currentLang === 'hi';

  const loadingText = TL('🤖 NuKrop AI Analyzing...', '🤖 NuKrop AI విశ్లేషిస్తోంది...', '🤖 NuKrop AI विश्लेषण कर रहा है...');

  box.innerHTML += `
    <div id="${aiMsgId}" style="background:#FFFFFF;border:1px solid #E2ECE2;border-radius:14px;padding:12px;font-size:12px;margin-bottom:8px;line-height:1.5;box-shadow:0 2px 6px rgba(0,0,0,0.03);">
      <div style="display:flex;align-items:center;gap:6px;color:#15803D;font-weight:800;font-size:11px;margin-bottom:4px;">
        <span>✨</span> <span>ICAR Groq AI Advisor</span>
      </div>
      <div class="ai-body">${loadingText}</div>
    </div>
  `;
  box.scrollTop = box.scrollHeight;

  const aiRes = await callGroqAI(txt);

  const aiBubble = document.getElementById(aiMsgId);
  if (aiBubble) {
    const bodyEl = aiBubble.querySelector('.ai-body');
    let finalReply = aiRes;
    if (!finalReply) {
      if (isTe) {
        finalReply = `<em>"${txt}"</em> కి సంబంధించి ICAR సిఫార్సు ప్రకారం, సమతుల్య NPK ఎరువులను వాడండి మరియు పైపాటుగా సూక్ష్మపోషకాలను పిచికారీ చేయండి.`;
      } else if (isHi) {
        finalReply = `<em>"${txt}"</em> के लिए ICAR कृषि विज्ञान अनुशंसा: संतुलित NPK पोषण दें और वानस्पतिक वृद्धि अवस्था में सूक्ष्म पोषक तत्वों का छिड़काव करें।`;
      } else {
        finalReply = `Based on ICAR agronomy recommendations for <em>"${txt}"</em>, ensure balanced NPK application and spray micronutrients during active vegetative growth.`;
      }
    }

    if (bodyEl) {
      bodyEl.innerHTML = finalReply.replace(/\n/g, '<br>');
    }
    box.scrollTop = box.scrollHeight;
  }
}


function playVoiceAudio(text) {
  if ('speechSynthesis' in window) {
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.rate = 0.95;
    window.speechSynthesis.speak(utterance);
  }
}

