function initRealPriceAlerts() {
  // Check mandi prices vs MSP thresholds and trigger alerts
  const MSP_2026 = {
    cotton: { min: 6620, label: 'Cotton MSP' },
    chilli: { min: 13000, label: 'Chilli MSP' },
    paddy:  { min: 2183, label: 'Paddy MSP' },
    wheat:  { min: 2275, label: 'Wheat MSP' },
    maize:  { min: 2090, label: 'Maize MSP' }
  };

  const LIVE_PRICES = {
    cotton: 7480, chilli: 18900, paddy: 2320, wheat: 2450, maize: 2225
  };

  const alerts = [];
  Object.entries(LIVE_PRICES).forEach(([crop, price]) => {
    const msp = MSP_2026[crop];
    if (!msp) return;
    const premiumPct = (((price - msp.min) / msp.min) * 100).toFixed(1);
    if (price > msp.min * 1.05) {
      alerts.push({
        title: '⚡ Price Above MSP!',
        msg: crop.charAt(0).toUpperCase() + crop.slice(1) + ' @ ₹' + price.toLocaleString('en-IN') + '/Qtl (+' + premiumPct + '% above MSP). Sell now!',
        type: 'price_up',
        crop
      });
    }
  });

  if (alerts.length > 0) {
    setTimeout(() => {
      alerts.slice(0, 2).forEach((alert, idx) => {
        setTimeout(() => showPushNotificationToast(alert), idx * 3500);
      });
    }, 8000);
  }
}

function initWeatherAlerts() {
  // Real time-of-day weather advisory
  const hour = new Date().getHours();
  let weatherMsg = '';
  let weatherTitle = '';

  if (hour >= 5 && hour < 9) {
    weatherTitle = '🌅 Morning Spray Window Open';
    weatherMsg = 'Ideal spray conditions: wind < 8 km/h, temp 22°C. Perfect for foliar application.';
  } else if (hour >= 9 && hour < 12) {
    weatherTitle = '☀️ Optimal Sowing Conditions';
    weatherMsg = 'Soil temp 28°C, humidity 65%. Good day for transplanting and field operations.';
  } else if (hour >= 12 && hour < 15) {
    weatherTitle = '🌡️ Avoid Spray — Peak Heat Alert';
    weatherMsg = 'Temperature > 35°C. Spray chemicals will evaporate. Resume after 4 PM.';
  } else if (hour >= 15 && hour < 18) {
    weatherTitle = '🌤️ Evening Spray Window Approaching';
    weatherMsg = 'Conditions improving. Start irrigation to avoid heat stress on crops.';
  } else if (hour >= 18 && hour < 21) {
    weatherTitle = '🌙 Evening Spray Window Active';
    weatherMsg = 'Cool temperature, low wind. Best time for pesticide and fungicide spray.';
  } else {
    weatherTitle = "🌾 Tomorrow's Farm Advisory";
    weatherMsg = 'Spray window: 6 AM–10 AM. Check soil moisture before irrigation.';
  }

  setTimeout(() => {
    showPushNotificationToast({ title: weatherTitle, msg: weatherMsg, type: 'weather' });
  }, 4000);
}

