/* Driver cockpit actions verified */



var selectedGramhaulTier = selectedGramhaulTier || 1;

function selectGramhaulTruckTier(tier) {
  selectedGramhaulTier = tier;
  document.querySelectorAll('#gh-truck-categories .gh-vehicle-card').forEach((el, idx) => {
    if (idx + 1 === tier) {
      el.classList.add('selected');
      el.style.borderColor = '#16A34A';
      el.style.background = '#F0FDF4';
    } else {
      el.classList.remove('selected');
      el.style.borderColor = '#E2E8F0';
      el.style.background = '#FFFFFF';
    }
  });
  recalcGramhaulFare();
}

function updateGramhaulMandi(idx) {
  const index = parseInt(idx);
  if (typeof REAL_APMC_MANDIS !== 'undefined' && REAL_APMC_MANDIS[index]) {
    currentGramhaulMandi = REAL_APMC_MANDIS[index];
    recalcGramhaulFare();
    if (typeof initGramhaulRealMap === 'function') {
      initGramhaulRealMap();
    }
  }
}

function recalcGramhaulFare() {
  const mandi = (typeof currentGramhaulMandi !== 'undefined' && currentGramhaulMandi) ? currentGramhaulMandi : (typeof REAL_APMC_MANDIS !== 'undefined' ? REAL_APMC_MANDIS[0] : { distKm: 7.2 });
  const dist = mandi.distKm || 7.2;
  const sacks = parseInt(document.getElementById('gh-weight-inp')?.value || '40') || 40;

  const f1 = Math.round(250 + dist * 16 + sacks * 1.5);
  const f2 = Math.round(350 + dist * 22 + sacks * 2.0);
  const f3 = Math.round(420 + dist * 26 + sacks * 2.5);
  const f4 = Math.round(600 + dist * 35 + sacks * 3.0);
  const f5 = Math.round(800 + dist * 45 + sacks * 3.5);

  const el1 = document.getElementById('gh-fare-tier-1');
  const el2 = document.getElementById('gh-fare-tier-2');
  const el3 = document.getElementById('gh-fare-tier-3');
  const el4 = document.getElementById('gh-fare-tier-4');
  const el5 = document.getElementById('gh-fare-tier-5');
  if (el1) el1.textContent = '₹' + f1;
  if (el2) el2.textContent = '₹' + f2;
  if (el3) el3.textContent = '₹' + f3;
  if (el4) el4.textContent = '₹' + f4;
  if (el5) el5.textContent = '₹' + f5;

  const fares = { 1: f1, 2: f2, 3: f3, 4: f4, 5: f5 };
  const total = fares[selectedGramhaulTier] || f1;
  selectedGramhaulPrice = total;
  const totalEl = document.getElementById('gh-total-fare');
  if (totalEl) totalEl.textContent = '₹' + total;
}

