function toggleTripDetailsDrawer() {
  const content = document.getElementById('gh-trip-details-content');
  const arrow = document.getElementById('gh-trip-arrow');
  if (!content) return;
  if (content.style.display === 'none' || !content.style.display) {
    content.style.display = 'flex';
    if (arrow) arrow.style.transform = 'rotate(180deg)';
  } else {
    content.style.display = 'none';
    if (arrow) arrow.style.transform = 'rotate(0deg)';
  }
}

function triggerDriverCall(driverName, phone) {
  const modalId = 'driver-live-call-modal';
  let modal = document.getElementById(modalId);
  if (modal) modal.remove();

  activeHaulCallSeconds = 0;

  modal = document.createElement('div');
  modal.id = modalId;
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,0.92);backdrop-filter:blur(10px);z-index:999999;display:flex;align-items:center;justify-content:center;animation:fadeIn 0.2s ease;';
  
  modal.innerHTML = `
    <div style="width:100%;max-width:380px;text-align:center;padding:24px;color:#FFFFFF;">
      <div style="width:90px;height:90px;border-radius:50%;background:#DCFCE7;border:3px solid #22C55E;margin:0 auto 16px;display:flex;align-items:center;justify-content:center;font-size:42px;box-shadow:0 0 30px rgba(34,197,94,0.4);">
        👨🏻‍💼
      </div>

      <div style="font-size:20px;font-weight:900;color:#FFFFFF;margin-bottom:4px;">${driverName}</div>
      <div style="font-size:13px;color:#22C55E;font-weight:700;margin-bottom:8px;">● Connected via NuKropAI Secure Call</div>
      <div id="haul-call-duration" style="font-size:15px;color:#94A3B8;font-weight:800;letter-spacing:1px;margin-bottom:30px;">00:01</div>

      <div style="display:flex;justify-content:center;gap:20px;margin-bottom:32px;">
        <button style="width:54px;height:54px;border-radius:50%;background:rgba(255,255,255,0.12);border:none;color:#FFFFFF;font-size:20px;cursor:pointer;">🎙️</button>
        <button style="width:54px;height:54px;border-radius:50%;background:rgba(255,255,255,0.12);border:none;color:#FFFFFF;font-size:20px;cursor:pointer;">🔊</button>
      </div>

      <button onclick="endDriverLiveCall('${modalId}')" style="width:68px;height:68px;border-radius:50%;background:#EF4444;border:none;color:#FFFFFF;font-size:26px;cursor:pointer;box-shadow:0 8px 24px rgba(239,68,68,0.4);display:inline-flex;align-items:center;justify-content:center;">
        ✕
      </button>
      <div style="font-size:12px;color:#94A3B8;margin-top:10px;font-weight:700;">End Call</div>
    </div>
  `;

  document.body.appendChild(modal);

  if (activeHaulCallTimer) clearInterval(activeHaulCallTimer);
  activeHaulCallTimer = setInterval(() => {
    activeHaulCallSeconds++;
    const durEl = document.getElementById('haul-call-duration');
    if (durEl) {
      const m = String(Math.floor(activeHaulCallSeconds / 60)).padStart(2, '0');
      const s = String(activeHaulCallSeconds % 60).padStart(2, '0');
      durEl.textContent = `${m}:${s}`;
    }
  }, 1000);
}

function endDriverLiveCall(modalId) {
  if (activeHaulCallTimer) {
    clearInterval(activeHaulCallTimer);
    activeHaulCallTimer = null;
  }
  const modal = document.getElementById(modalId);
  if (modal) modal.remove();
  if (typeof showLuxuryToast === 'function') {
    showLuxuryToast('Call Ended', 'info');
  }
}

